INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('1', '1', 'Student Council Election', 'The Student Council Election was a remarkable event that highlighted the spirit of leadership and democracy among our students. Aspiring candidates delivered passionate speeches and presented their manifestos, showcasing their vision for their peers. The voting process, conducted with utmost transparency, fostered a sense of responsibility and decision-making in the student body. Congratulations to all the elected members!', '67207a1a78dbf.jpeg', '2024-10-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('2', '2', 'Independence Day Celebration', 'Our Independence Day Celebration was a vibrant display of patriotism and unity. Students participated in various activities, including speeches, cultural performances, and national songs, honoring the sacrifices of our forefathers. The school echoed with pride as everyone came together to celebrate the spirit of freedom', '67063f69ef7d3.jpeg', '2024-08-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('3', '2', 'Sports Day', 'The Sports Day was a thrilling event filled with energy, enthusiasm, and sportsmanship. Students competed in various athletic events, from races to team sports, showcasing their skills and determination. The day emphasized the importance of physical fitness and teamwork, leaving everyone inspired', '66fcebdf7c2c5.png', '2024-09-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('4', '2', 'Spelling Bee', 'The Spelling Bee competition was an intellectual treat, where students demonstrated their linguistic skills and vocabulary mastery. Each round brought excitement and applause, as participants showcased their hard work and dedication. Congratulations to the winners for their exceptional performance!', '67060dadb7379.png', '2024-09-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('5', '2', 'Defense Day', 'The Defense Day celebration was a heartfelt tribute to the brave heroes of our nation. Students expressed their gratitude and respect through speeches, skits, and patriotic songs. The event served as a reminder of the sacrifices made for our freedom and the unity that binds us as a nation.', '66fe38198490a.jpeg', '2024-09-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('6', '2', 'Mental Math Competition', 'Our Mental Math Competition was an exhilarating showcase of quick thinking and numerical prowess. Students from various grades participated enthusiastically, solving complex problems with speed and accuracy.\r\n\r\nThe competition aimed to enhance mental calculation skills, boost confidence, and encourage a love for mathematics. Participants impressed everyone with their ability to tackle challenging questions under time constraints.\r\n\r\nEvents like these continue to inspire a passion for learning and a competitive spirit among our students', '670757473a83b.jpg', '2024-09-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('8', '2', 'Certificate distribution Ceremony of IKCC', 'The Certificate Distribution Ceremony of the International Kids Coding Competition (IKCC) celebrated the creativity and achievements of young coders. 20 students from SKANS campuses, including Golra, Westridge, AECHS, Harley, and Chakri, participated. Chief Guest Miss Samina Raja and Mr. Abdullah Qureshi inspired attendees with motivational speeches. Certificates were awarded to all participants, with special awards for top performers. The event concluded with a group photo, encouraging young learners to excel in coding and innovation', '6753ed1643c6a.jpeg', '2024-11-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('9', '1', 'Position held at Robian Competition', 'A Proud Moment of Innovation and Excellence!✨\r\n\r\nOur brilliant students from AECHS Campus Eshal Zafar Class Pre-9th, Shahmeer Atiq &amp;amp; Anaya Amir Class 7, Aroosh Binte Usman Class 6 participated in the Robian Competition at COMSATS University on Sunday, 15th December, 2024, showcasing their incredible talent and innovation by presenting their robots with immense confidence!  They impressed everyone by explaining its features, functionality, and technicalities in detail.\r\n\r\nWe are thrilled to announce that they secured 2nd position at the university-level competition – a truly remarkable achievement! \r\n Kudos to our young innovators for their hard work and dedication. They’ve made us all proud!', '676134e446856.jpeg', '2024-12-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('10', '1', 'Commencement of Mid-Year Exams!', 'Our students are having their exams with focus and confidence, showing determination and hard work. It’s inspiring to see their dedication and commitment in action. We are feeling proud of all our learners and are wishing them continued success for the remaining exams. They are staying prepared, staying positive, and keeping up the great work! \r\n\r\n#MidYearExams #HardWorkInAction #StayFocused #ProudMoment', '67691002b47d5.jpeg', '2024-12-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('11', '2', 'Professionals Day', 'Children of Early years enthusiastically participated in Professional Day by dressing up as various professionals, proudly showcasing their dreams and aspirations. From doctors and engineers to teachers and artists, each learner represented a profession that inspired them, reflecting their ambitions and creativity.\r\n\r\nThe activity aimed to encourage students to think about their future goals while fostering self-confidence and awareness about different career paths. Their vibrant costumes and confident presentations highlighted their excitement and dedication to their dreams.\r\n\r\nThis engaging event truly celebrated the potential of our future leaders, leaving everyone inspired and proud of their shining aspirations.\r\n\r\n#DreamBig #FutureLeaders', '676913aea221a.jpeg', '2024-12-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('12', '2', 'Winter Activity Day 1: Cupcake Decoration Fun!', 'Our Winter Activity Week kicked off with an exciting cupcake decoration session! Students unleashed their creativity as they turned plain cupcakes into delightful works of art. With colorful frostings, sprinkles, and edible decorations, each cupcake became a unique masterpiece. The activity not only encouraged artistic expression but also strengthened fine motor skills and fostered teamwork. Laughter and joy filled the room as students proudly displayed their decorated treats. It was heartwarming to see their faces light up with accomplishment. This sweet start set the tone for a fun-filled week ahead, celebrating the winter season with creativity and enthusiasm', '676d0d02aba42.jpeg', '2024-12-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('13', '1', 'Heartiest Congratulations to the CATSO Competition Winners!', 'We are thrilled to celebrate the outstanding achievements of our talented students:\r\n\r\n1- Haris Bin Sadiq (Class 1) - Gold Medal in Arts\r\n2-  Syeda Fariyah Jawad (Class 2) - Gold Medal in English Quiz\r\n3-  Haris Bin Sadiq (Class 1) - Bronze Medal in English Quiz\r\n4-  Abrish Bilal (Class 3-A) - Special Giveaway in Arts\r\n5-  Aroush Bint Sadiq (Class 4-A) - Special Giveaway in Arts\r\nThis hard work and determination have made us all proud. Keep up the great work! \r\n#CATSOCompetition #StudentAchievements #ProudMoment #SKANSSchoolSystem', '67778734f1399.jpeg', '2025-01-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('14', '2', 'AN UNFORGETTABLE DAY AT CHINAR GOLF CLUB WITH OUR AMAZING STUDENTS!', 'The lush greenery, crisp mountain air, and serene beauty of Chinar Golf Club set the perfect stage for a day filled with exploration, fun, and learning. From enjoying the scenic landscapes to bonding with friends and teachers, the students embraced every moment with excitement and curiosity. Their bright smiles and cheerful laughter echoed through the hills, making this trip truly memorable.\r\n\r\nSuch experiences are not just about fun but also about creating cherished memories, fostering friendships, and learning outside the classroom.\r\n#StudentAdventures #ChinarGolfClub #Bhurban #NatureLovers #GolfTrip #MemorableMoments', '677ce88099871.jpeg', '2025-01-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('15', '1', 'MYE Result Day', 'Mark your calendars! Result Day is on Saturday, 11th January 2025. Let’s gear up to celebrate the achievements and progress of our amazing students! ????\r\n\r\n#SKANSAECHS #ResultDay #MidTermResult', '677ce96cebcf0.jpeg', '2025-01-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('16', '1', 'Team AECHS Campus on Open Day', 'A team that works together, shines together!\r\nOur dedicated and hardworking staff poured their hearts into making Open Day a huge success! From planning to execution, every detail reflected their passion, commitment, and teamwork.\r\nWe are a proud team of SKANS AECHS Campus, and this achievement belongs to each one of us!\r\n#ProudTeam #SKANSaechs #OpenDaySuccess #TeamworkAtItsBest #Dedication #HardWorkPaysOff #StrongerTogether #UnforgettableMoment', '67bc1db2b89c1.jpeg', '2025-02-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('17', '2', 'Open Day Taekwondo Display', 'Our talented Grade 4 students showcased an energetic and disciplined display of Taekwondo and PT on Open Day! Their dedication, strength, and teamwork were truly commendable. A big round of applause for their hard work and enthusiasm!!', '67bc2223d8004.jpeg', '2025-02-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('18', '2', 'Aerobics Display on Open Day', 'Our talented girls put on a spectacular aerobics performance, showcasing strength, flexibility, and rhythm. Their passion and enthusiasm lit up the stage, making it a performance to remember!\r\n#AerobicsPerformance #GirlPower #SKANSaechs #OpenDay2025 #StrengthAndGrace #FitnessInMotion #EnergyUnleashed #ProudMoment #RhythmAndMoves #ConfidenceAndTalent', '67bc25e5d9a08.jpeg', '2025-02-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('19', '1', 'Orientation Session (IMO)', 'Dear Parents,\r\nWe are delighted to invite you and your child to an exclusive motivational session aimed at encouraging students to participate in the International Mathematics Olympiad (IMO) Preparation Program. This program serves as a pathway to the National Mathematics Talent Competition (NMTC) and ultimately leads to the prestigious International Mathematics Olympiad (IMO).\r\nEvent Details\r\nVenue: AECHS Campus, Rawalpindi\r\nDate: Wednesday, 26th February 2025\r\nTime: 12:30 PM\r\nTarget Audience: Students from Class 6 to Pre-9 and their Parents\r\nThe International Mathematics Olympiad (IMO) is one of the most prestigious and intellectually challenging competitions for students worldwide. It provides young minds with a platform to showcase their mathematical talent while also strengthening their problem-solving abilities. Participating in such competitions not only builds confidence but also enhances logical reasoning and analytical skills, preparing students for future academic challenges.\r\nWhy Attend This Session?\r\n\r\nThis motivational session has been specifically designed to help students and parents understand the importance of competitive mathematics and how to prepare effectively for such competitions.', '67bc3baa8e468.jpeg', '2025-02-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('20', '2', 'Orientation Session on IMO Preparation at SKANS AECHS Campus', 'SKANS AECHS Campus hosted an engaging Orientation Session on the International Mathematics Olympiad (IMO) Preparation Program. With insights from guest speaker Ms. Samina Raja, students gained valuable strategies to excel in the prestigious competition. A great initiative to inspire young mathematicians!', '67c025219d653.jpg', '2025-02-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('21', '1', 'Upcoming Urdu Speech Competition at SKANS School System', 'SKANS School System is all set to host an inter-class Urdu Speech Competition on March 3rd 2025. A platform for students to showcase their eloquence and celebrate the richness of the Urdu language. Stay tuned for an inspiring display of oratory skills!', '67c025e21c561.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('22', '1', 'Friday Learning Takeaways: Fun Beyond the Classroom!', 'Every Friday, children take home special learning takeaways that reinforce classroom concepts in a fun and engaging way. These activities encourage creativity, critical thinking, and parent involvement in their learning journey. It’s a great way to extend learning beyond the classroom!', '67c177e9761a7.jpeg', '2025-02-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('23', '1', 'We are Hiring!', 'SKANS School is hiring a teacher for the Early Years Education (EYE) section at their AECHS Campus in Rawalpindi. Candidates must have a graduation degree from a reputed institution along with Early Years Training and at least one year of teaching experience. Interested applicants can send their CVs to hr@skans.pk.', '67c1cff283130.jpg', '2025-02-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('24', '1', 'Ramadan Kareem!', 'Embracing the blessings of Ramadan with gratitude and devotion – Ramadan Kareem from SKANS!', '67c54cd807c8b.jpg', '2025-03-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('25', '1', 'Embracing the Spirit of Ramadan with activities!', 'SKANS School System is celebrating the holy month of Ramadan with a series of engaging and meaningful activities for students from Class 3 to Pre 9. From essay writing and speech competitions to assemblies on the benefits of Ramadan, charity drives, and interactive learning about prayer, our program is designed to instill values of faith, generosity, and knowledge. Stay connected as we embrace the spirit of Ramadan together!', '67c54ebe357e6.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('26', '1', 'Ramadan Celebrations in Early Years at SKANS!', 'Our youngest learners at SKANS are celebrating Ramadan with creativity and reflection. From Welcome Ramadan Crafts to storytime about Prophet Muhammad (PBUH) and motivational assemblies, each activity nurtures faith, kindness, and gratitude. Fun tasks like Suhoor &amp; Iftar plate coloring make learning about Ramadan engaging, fostering a sense of spirituality and togetherness.', '67c54f76424d4.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('27', '2', 'Assembly Presentation on the Blessings of Ramadan!', 'Pre-9 students beautifully and thoughtfully presented the blessings of the holy month of Ramadan during the assembly. They highlighted the spiritual, physical, and social benefits of Ramadan, emphasizing that this month is not only a means of gaining closeness to Allah but also fosters patience, gratitude, piety, and an increase in good deeds.', '67c7156fe8476.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('28', '1', 'Welcome to SKANS, Minahil!', 'Wishing you a wonderful learning journey filled with growth, fun, and new adventures!', '67c7179d7ddff.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('29', '1', 'Welcoming the Blessings of Ramadan', 'SKANS School System proudly presents a Ramadan speech competition for students of grades 5, 8, and 9. Join us as we celebrate the virtues, blessings, and spiritual significance of this holy month. Mark your calendars for March 5, 2025, and witness young minds express the essence of Ramadan with passion and eloquence!', '67c719fc3cc30.jpg', '2025-03-01');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('30', '2', 'Shapes all around!', 'Our curious little learners of Class 2-B had an exciting and interactive circle time, diving into the world of 2D and 3D shapes! From flat squares to solid cubes, they explored, compared, and discovered the unique features of each shape in a fun and engaging way!', '67c71b01c7158.jpg', '2025-03-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('31', '1', 'Ramadhan Kareem Speech Competition!', 'SKANS School System is hosting a Speech Competition on the Blessings of Ramadan for students from Class 5 to Pre-9th on Thursday, 6 March 2025. Stay tuned for an inspiring showcase of eloquence and faith!', '67c8790a894cf.jpg', '2025-03-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('32', '2', 'Urdu Speech Competition – Encouraging Expression from Early Years (EYE)!', 'SKANS AECHS hosted an Urdu Speech Competition, fostering confidence and eloquence among students, including our Early Years Education (EYE) learners. \r\nWith expressive delivery and a rich choice of words, participants showcased their linguistic skills beautifully. This event not only emphasized the importance of language but also enhanced students confidence and communication abilities.', '67c87d1d8eed9.jpg', '2025-03-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('33', '2', 'Senior Students Shine in Speech Competition on the Blessings of Ramadan!', 'In the speech competition on the Blessings and Virtues of Ramadan, senior students showcased outstanding performances, eloquently expressing their thoughts with confidence and depth. \r\n\r\nTheir powerful speeches reflected a deep understanding of Ramadan’s spiritual significance, highlighting its virtues with wisdom and grace. The competition served as a platform to enhance their public speaking skills and strengthen their connection to Islamic teachings.', '67c87da6e180b.jpg', '2025-03-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('34', '2', 'Class 2-B’s Enlightening Ramadan Assembly!', 'Our Class 2-B students delivered a thoughtful assembly on the do’s and don’ts of Ramadan, sharing meaningful reflections on the importance of this sacred month. A wonderful display of knowledge and understanding!', '67ca77f6cbc96.jpg', '2025-03-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('35', '1', 'SKANS Charity Drive – Make a Difference!', 'Join us in our mission to help those in need! Donate essential items like clothes, food, stationery, blankets, and more. Your generosity brings hope! Drop off your donations by Wednesday, 12th March 2024. Let&amp;#039;s make a difference together!', '67cea3119c4d1.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('36', '1', 'SKANS Pre-Board Result Day – March 11, 2025', 'Attention Parents &amp;amp; Students! SKANS School System is hosting Pre-Board Result Day on March 11, 2025, from 9:00 AM to 11:00 AM. Parents are requested to personally visit the school to collect their child&amp;#039;s result and roll number slip. See you there!', '67cf9bdfa5ffe.jpg', '2025-03-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('37', '2', 'Booster Session on Curriculum Adaptation', 'Dedicated educators engage in a collaborative booster session on curriculum adaptation, exchanging ideas and strategies to enhance lesson effectiveness. Their commitment to fostering an enriching learning environment shines through!', '67d143815b3e0.jpg', '2025-03-12');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('38', '2', '9th &amp;amp; 10th Pre-Board Result &amp;amp; PTM', 'Productive discussions at the Parent-Teacher Meeting (PTM) for 9th &amp;amp; 10th pre-board results! Engaging parents in their child&amp;#039;s academic journey fosters growth, motivation, and success. Together, we strive for excellence!', '67d1447b14741.jpg', '2025-03-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('39', '2', 'Celebrating Mirha’s Special Day!', 'Today, we celebrated Mirha’s birthday with joy and laughter! Her kindness and generosity bring so much happiness to our little learners. Just like the cakes and candies she shared, may her life be filled with sweetness, happiness, and endless blessings. Wishing her a wonderful year ahead!', '67d3d70e97c6f.jpg', '2025-03-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('40', '2', 'Special Assembly on the Spirit of Ramadan!', 'Teachers led a meaningful and inspiring special assembly on the importance of Ramadan—a month of faith, self-discipline, and generosity. It was a wonderful opportunity to reflect on its true essence, purify our hearts, and strengthen our connection with Allah. Grateful to share these valuable lessons with our students!', '67d3d92206673.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('41', '2', 'Namaz Day – A Spiritual Reflection!', 'Senior students observed Namaz Day with devotion, embracing the power of prayer in their daily lives. A reminder that Salah instills discipline, strengthens faith, and guides us toward righteousness. May we continue to find peace and purpose through our prayers.', '67d3d9912dfc4.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('42', '2', 'Namaz Day – A Special Moment for Our EYE Learners!', 'Our little EYE learners participated in Namaz Day with enthusiasm, learning the importance of prayer in their daily lives. It’s heartwarming to see them take their first steps in understanding faith, discipline, and gratitude through Salah.', '67d3da3e8487f.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('43', '2', 'Inspiring Speeches on Kindness &amp; Good Deeds!', 'Our bright students from Class 3 to 7 delivered wonderful one-minute speeches on Kindness and Good Deeds. Their heartfelt words reminded us that even the smallest acts of kindness can create a big impact. Proud to see them embracing these values with confidence and enthusiasm!', '67d3db8b6afa2.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('44', '2', 'Celebrating the Magic of Mathematics on International Math Day!', 'We dived into the fascinating world of numbers, patterns, and logical thinking in honor of International Math Day! From engaging math puzzles and brain-teasing challenges to hands-on activities and creative problem-solving, our learners explored how mathematics shapes our world. More than just numbers and formulas, math is a universal language that connects technology, nature, and everyday life. A day full of curiosity, discovery, and fun!', '67d8da4e337fa.jpg', '2025-03-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('45', '2', 'Playgroup&#039;s Adorable Morning Assembly on Vegetables!', 'Our little stars from Playgroup lit up the stage with their delightful Morning Assembly Presentation on vegetables. With bright smiles and confident voices, they showcased their learning in the most charming way. A big applause for their enthusiasm and effort—keep growing and shining!', '67dbc73fd7e7a.jpg', '2025-03-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('46', '2', 'Kindergarten Islamiat Quiz Challenge!', 'Our little kindergarten stars participated in an exciting Islamiat quiz today! Their enthusiasm, bright smiles, and incredible efforts made the learning experience even more special. We’re so proud of them!', '67dbc7cbba418.jpg', '2025-03-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('47', '2', 'A Spiritually Uplifting Quran Recitation', 'A heartfelt recitation of the Holy Quran was held at our school during the blessed month of Ramadan. This spiritually enriching moment strengthened our faith and brought peace to our hearts. May Allah guide us to understand and follow the teachings of the Quran. Ameen!', '67dccfebcc2c4.jpg', '2025-03-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('48', '2', 'A Heartwarming Iftar – Embracing the Spirit of Ramadan!', 'Our school had the honor of hosting a special Iftar, bringing together students, teachers, and underprivileged children in an evening filled with kindness and compassion. Sharing this meal reminded us of Ramadan’s true essence—generosity, gratitude, and togetherness. May Allah accept our prayers and guide us to always support those in need.', '67de4a18b050e.jpg', '2025-03-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('49', '2', 'Little Stars Shine on Pakistan Day!', 'Our adorable young learners celebrated 23rd March with vibrant performances, patriotic chants, and creative artwork, showcasing their love for Pakistan in the sweetest way!', '67e2125c42504.jpg', '2025-03-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('50', '2', 'Honoring Pakistan Day with Pride &amp; Passion!', 'Our senior students marked 23rd March with powerful speeches, heartfelt performances, and a true spirit of patriotism, reflecting on the sacrifices and values that define our nation!', '67e2129969fb5.jpg', '2025-03-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('51', '2', 'Celebrating the spirit of Pakistan!', 'Our dedicated staff came together to commemorate Pakistan Day with pride, unity, and patriotism. Together, we honor the sacrifices of our heroes and pledge to contribute to a brighter future for our beloved country.', '67e4287b376f1.jpg', '2025-03-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('52', '2', 'Strengthening Bonds for Student Success!', 'A successful Parent-Teacher Meeting was held today, fostering meaningful discussions on student progress and learning goals. Grateful for the collaboration and dedication of our parents and teachers in shaping a bright future for our students!', '67e4b93e133ed.jpg', '2025-03-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('53', '2', 'Successful Parent-Teacher Meeting for Senior Classes!', 'Today&#039;s PTM for senior classes was a great success! It fostered meaningful discussions between teachers and parents, strengthening our shared commitment to student growth and achievement. Grateful for the collaboration and support!', '67e57fa39b34a.jpg', '2025-03-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('54', '2', 'Eid Cheer with Our Wonderful Staff!', 'Spreading a little joy before Eid! We shared small tokens of appreciation with our dedicated staff as they prepare to celebrate Eid-ul-Fitr with their loved ones. Their smiles made the moment even more special. Wishing everyone a blessed and joyous Eid—may it be filled with happiness, relaxation, and cherished moments with family.', '67e5813502b8f.jpg', '2025-03-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('55', '2', 'Eid Milan Magic in EYE!', 'Eid Milan Party vibes were absolutely magical in our EYE section!  The little ones sparkled in their festive outfits, shared treats, and spread smiles all around. From joyful dances to heartfelt hugs, the day was filled with laughter, love, and unforgettable moments with friends. It was a beautiful celebration of togetherness and joy, leaving everyone with sweet memories to cherish.', '67f4012a7ccc8.jpg', '2025-04-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('56', '2', 'Eid Milan Celebration – A Festive Day of Joy, Togetherness, and Smiles!', 'Eid Milan celebrations in our senior classes were full of festive spirit and vibrant energy! Students bonded over fun games, joyful conversations, and delicious treats, creating moments of laughter and togetherness. The beautiful blend of tradition and friendship made the day truly special. Here&#039;s to celebrating Eid with love, unity, and lots of smiles!', '67f402f17a693.jpg', '2025-04-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('57', '2', 'Sports Day 2025 | A Celebration of Strength &amp;amp; Spirit', 'Our school grounds came alive with energy, excitement, and enthusiasm as students showcased their athletic talents during Sports Day 2025! From thrilling races to team challenges, every moment echoed with cheers, sportsmanship, and joy. A day of fun, fitness, and fantastic memories!', '67ff15b58d25b.jpg', '2025-04-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('58', '2', 'Power, Precision, and Passion – Taekwondo Display on Sports Day!', 'Our young martial artists stole the spotlight with a dynamic Taekwondo performance on Sports Day! With powerful kicks, sharp moves, and unwavering focus, they demonstrated strength, discipline, and confidence. A proud moment showcasing the spirit of sportsmanship and self-belief!', '6800b7379c128.jpg', '2025-04-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('59', '2', 'PT Display – A Striking Showcase of Strength and Unity!', 'Strength, discipline, and unity in every move! Our boys delivered a powerful PT Display that captivated the audience and echoed the true essence of sportsmanship. With synchronized steps, focused energy, and proud expressions, they marched with pride and purpose. A moment to remember!', '6800b8057c581.jpg', '2025-04-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('60', '1', 'Earth Day 2024 – Nurturing Young Eco-Champions!', 'In celebration of Earth Day, our school is buzzing with green energy as students come together to honor the beauty and importance of our planet. With a focus on sustainability, students are participating in a series of engaging and educational activities designed to promote environmental awareness and responsibility.\r\n\r\nFrom hands-on crafts using recycled materials to thoughtful discussions on eco-friendly habits, the initiative aims to instill a deep sense of care and stewardship in our young learners. These activities not only highlight the urgent need to protect natural resources but also encourage students to become proactive change-makers in their communities.\r\n\r\nStay tuned as we capture and share heartwarming moments from this meaningful celebration. Together, we’re planting the seeds for a greener, cleaner future!', '68012fe5bbac9.jpg', '2025-04-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('61', '1', 'Curtains Rising Soon – Drama Festival 2025 is Almost Here!', 'Lights, camera, excitement! Our stage is set for the upcoming Drama Festival, where creativity meets performance. Get ready to witness unforgettable moments as our talented students bring characters and stories to life. Stay tuned — the spotlight is waiting!', '6801306a04426.jpg', '2025-04-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('62', '2', 'A Blessed Friday of Prayers and Kindness!', 'We began this beautiful Friday with heartfelt prayers and du’as, setting a peaceful tone for the day. The joy continued as we celebrated our Courtesy Kings and Queens—crowned for their kindness and respectful behavior. Congratulations to all our little royals for shining so brightly!', '68064c30d267e.jpg', '2025-04-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('63', '2', 'Eco Champs: Earth Day Quiz Challenge', 'Students put their green knowledge to the test during our Earth Day Quiz! With buzzing brains and bright smiles, they answered questions about our planet, conservation, and how to be eco-friendly heroes. Learning about Earth has never been this exciting!', '6807e61937a09.jpg', '2025-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('65', '2', 'Earth Speaks: A Skit for Change', 'Our young performers took the stage this Earth Day with a powerful skit that gave voice to our planet. Through expressive storytelling and heartfelt messages, they highlighted the importance of conservation, recycling, and loving the Earth. A standing ovation for their passion and purpose!', '6807e68aedcec.jpg', '2025-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('66', '2', 'Together for Earth: Special Assembly in Celebration of Earth Day', 'Today’s special Earth Day assembly brought our school community together with powerful speeches, thoughtful presentations, and an interactive quiz — all aimed at raising awareness about protecting our environment. Students shared inspiring ideas on how we can make a difference. Let’s continue to work hand in hand for a greener, healthier planet!', '6807e6ee69dac.jpg', '2025-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('67', '2', 'Earth Day Echoes: Voices of 2B', 'Our little stars from Class 2B lit up the stage with their Earth Day performance! With passion in their hearts and purpose in their words, they shared meaningful messages on how to protect and preserve our beautiful planet. From planting trees to saving water, every voice spoke with love for Mother Earth. A performance that truly touched hearts and inspired minds!', '6807e7ea32921.jpg', '2025-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('68', '1', 'Bloom with Care Workshop', 'SKANS School System, AECHS Campus, is set to host a special hygiene awareness workshop titled “Bloom with Care.” This upcoming event aims to educate and empower young girls by promoting essential self-care and hygiene practices in a safe and supportive environment. With a focus on building confidence and well-being, the workshop reflects the school’s continued commitment to holistic student development. Stay tuned for more updates as we prepare to bloom together with care!', '680a813d22bf2.jpg', '2025-04-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('69', '1', 'Earthquake Evacuation Drill to Promote Safety Awareness', 'In an effort to strengthen emergency preparedness, SKANS School System, AECHS Campus, will conduct an Earthquake Evacuation Drill across the entire school campus. The initiative aims to equip students and staff with essential skills to respond calmly and efficiently during seismic events. The drill underscores the school’s ongoing commitment to student safety and disaster readiness.', '680a81e10c3df.jpg', '2025-04-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('70', '1', 'Early Years Grand Assembly Coming Soon', 'Excitement is building as the Early Years prepare for their Grand Assembly! This much-awaited event will feature our young learners proudly displaying what they’ve learned through creative presentations and performances. Parents and guardians are encouraged to attend and show their support. It&#039;s a perfect opportunity to celebrate growth, effort, and those unforgettable early milestones. Stay tuned!', '6810d861dae04.jpg', '2025-04-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('71', '2', 'Wall of Honour &amp; Courtesy King and Queen Awards', 'Congratulations to all the shining achievers featured on our Wall of Honour! Your hard work, positive attitude, and dedication truly deserve to be celebrated.\r\n\r\nA special round of applause for our Courtesy King and Queen—your kindness, respect, and graceful manners set a beautiful example for your peers.\r\n\r\nKeep shining bright, little stars! Your journey of excellence has just begun, and we’re so proud of each one of you!', '6810da747fb5c.jpg', '2025-04-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('72', '2', 'Empowered Girls: Hygiene Workshop for Our Young Ladies', 'Empowered girls, blooming with care!\r\nOur recent hygiene workshop was designed especially for our young ladies, focusing on the importance of self-care, cleanliness, and confidence. Through engaging discussions and fun activities, the session encouraged healthy habits and body positivity—planting the seeds of empowerment early.\r\nA thoughtful and informative event where learning met care, and confidence bloomed!', '6811e00097177.jpg', '2025-04-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('73', '1', 'Honoring the Spirit of Labour – 1st May', 'This Labour Day, SKANS pays tribute to the dedication, hard work, and resilience of workers everywhere.\r\nLet us recognize the value of every effort, big or small, that contributes to the growth of our communities.\r\nHere’s to dignity in work and pride in every role — today and every day.\r\n\r\nHappy Labour Day!', '6811e1ad3b93b.jpg', '2025-05-01');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('74', '1', 'A Proud Milestone: Graduation Ceremony for the Class of 2025', 'On Tuesday, 6th May 2025, SKANS School System will joyfully celebrate the achievements of its graduating Class of 2025. The event promises to be filled with proud smiles, heartfelt moments, and a festive spirit as students prepare to embrace their journey ahead.', '6816ea53d090c.jpg', '2025-05-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('75', '2', 'Grand Assembly on Clean Water and Sanitation – SDG Goal 6', 'In our Grand Assembly on Clean Water and Sanitation (SDG Goal 6), the young learners of Playgroup confidently showcased their understanding of hygiene, safe drinking water, and clean surroundings. Through expressive speeches and thoughtful messages, they highlighted the global importance of clean water access and the role each individual plays in achieving this vital goal.', '6816eca3b0825.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('76', '2', 'Grand Assembly on Climate Action – SDG Goal 13', 'In our Grand Assembly on Climate Action (SDG Goal 13), our little stars highlighted the importance of protecting our planet to ensure a safe and healthy future for all. Through songs, speeches, and role-plays, they shared how climate action can help reduce global pollution. With great enthusiasm and empathy, they encouraged everyone to take simple steps—like reducing pollution, planting trees, and conserving water—to contribute to a cleaner and greener world.', '6816ed374daa9.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('77', '2', 'Playgroup Champions SDG Goal 6 – Clean Water and Sanitation', 'Our little change-makers from Playgroup stole the show as they confidently presented SDG Goal 6: Clean Water and Sanitation. From the importance of clean hands to saving every precious drop, they reminded us that small actions can lead to a healthier, cleaner world. We are so proud of our youngest voices speaking up for a better tomorrow.', '6816edb58e1a0.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('78', '1', 'Grand Assembly Begins with a Purposeful Start Toward SDG Awareness', 'The Grand Assembly held at SKANS School System commenced on an inspiring note as students and staff gathered to begin the day with the name of Allah, followed by the National Anthem. This solemn and proud beginning set the tone for a purposeful morning focused on the Sustainable Development Goals (SDGs).\r\n\r\nThe event aimed to instill awareness and responsibility in young minds about the global challenges we face and the actions we must take to overcome them. It was a meaningful start to a day filled with thought-provoking performances, informative presentations, and a shared spirit of unity, learning, and national pride.', '6816ee66e3cbe.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('79', '2', 'Nursery B Shines Bright with Their Presentation on SDG Goal 2 – Zero Hunger', 'Our sweet stars from Nursery B took the stage with a heartwarming presentation on SDG Goal 2 – Zero Hunger. Through their meaningful performance, they conveyed the importance of sharing, caring, and working together to ensure that no one goes to bed hungry.\r\n\r\nTheir message, simple yet powerful, served as a gentle reminder that even the smallest voices can spark big change. We are incredibly proud of our little hearts for spreading awareness on such a vital global issue with so much compassion and confidence.', '6816ef215b5bb.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('80', '2', 'KG-A Brings SDG Goal 15 – Life on Land to Life', 'Our nature-loving learners from KG-A took the audience on a vibrant journey through forests, fields, and farms as they presented SDG Goal 15 – Life on Land. With heartfelt messages about protecting animals, planting trees, and preserving natural habitats, their performance emphasized the importance of caring for all living things around us.\r\n\r\nTheir energy, enthusiasm, and genuine concern for the environment left a lasting impression, inspiring everyone to take part in loving and protecting our precious planet.', '6816ef9e59eeb.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('81', '2', 'Ocean Explorers of KG-B Dive Into SDG Goal 14: Life Below Water', 'Our young ocean explorers from KG-B made a splash with their incredible presentation on SDG Goal 14!  They showcased the wonders of marine life and the importance of protecting our oceans. A round of applause for these little champions of the deep blue sea!', '6816f07e2ff1f.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('82', '2', 'Class 1 Sparks Change with SDG Goal 7: Affordable and Clean Energy', 'Class 1 lit up the stage with their dynamic performance on SDG Goal 7! With vibrant energy and thoughtful actions, they highlighted the importance of saving electricity and embracing clean energy for a brighter future. Shining bright with awareness and enthusiasm — well done, young changemakers!', '6816f11d91822.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('83', '2', 'Class 2B Promotes SDG Goal 3: Embracing Good Health and Well-Being!', 'Our little wellness warriors from Class 2B beautifully presented SDG Goal 3 — Good Health and Well-Being! From brushing teeth to eating healthy and staying active, they reminded us how small habits make a big difference.  A cheerful performance with a powerful message — healthy kids, happy future!', '6816f44ca1896.jpg', '2025-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('84', '1', 'SKANS School Drama Festival Shines with Captivating Urdu and English Performances', 'The SKANS School System&#039;s Drama Festival held on May 2nd was a resounding success, showcasing the exceptional talent of students in both Urdu and English plays. The event featured a diverse array of performances that captivated the audience and highlighted the students&#039; dedication and creativity.', '6816f645802c8.jpg', '2025-05-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('85', '2', 'SKANS School Drama Festival 2025', 'The SKANS School Drama Festival 2025 was a vibrant celebration of student creativity and theatrical talent. Held on May 2nd at the AECHS Campus in Rawalpindi, the event featured a series of captivating Urdu and English plays performed by students across various classes. The performances showcased the students&#039; dedication and passion for the dramatic arts, leaving the audience thoroughly entertained and impressed. This festival not only highlighted the artistic abilities of the students but also fostered a sense of community and cultural appreciation within the school', '6816f6e22ee74.jpg', '2025-05-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('86', '2', 'Professionalism in Practice: Leading with Purpose and Integrity', 'Uplifting standards and refining attitudes, our recent workshop on Professionalism empowered participants to lead with purpose and integrity. Through engaging discussions and practical exercises, attendees explored the core values that define true professionalism, leaving inspired to embody these principles in their daily work.', '6816f7d72dd24.jpg', '2025-05-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('87', '2', 'Defence Day Celebration', 'Our students enthusiastically celebrated Defence Day with great patriotism and respect for the sacrifices of our national heroes. The program included heartfelt speeches, national songs, tableaus, and poetry recitations that highlighted the bravery of the armed forces who defended our beloved homeland.\r\nThe event not only instilled national pride but also reminded the young learners of the importance of unity, courage, and love for Pakistan. Students actively participated with passion, paying tribute to the martyrs and renewing their pledge to serve the country with dedication.', '68c07987ef83b.jpeg', '2025-09-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('88', '2', 'Phonics Pathway to Literacy', 'We are pleased to announce an upcoming Phonics Workshop for Parents at SKANS. The session, “Phonics Pathway to Literacy,” will focus on guiding parents to effectively support their child’s early literacy journey — from understanding sounds to becoming confident readers.', '68d1948de73ef.jpg', '2025-09-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('89', '2', 'Donations Handed Over to Alkhidmat Foundation', 'At SKANS, we believe in nurturing empathy alongside education. Our school community came together to contribute towards flood relief efforts, and the donations were handed over to Alkhidmat Foundation. This initiative reflects our commitment to instilling compassion, social responsibility, and the spirit of giving back.', '68e3ad65a2de5.jpeg', '2025-09-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('90', '1', 'Student Council Election Campaign 2025', 'The *Election Campaign 2025* at our school created an atmosphere of excitement, energy, and healthy competition across all sections. Students enthusiastically took part in the campaign, showcasing their leadership skills, creativity, and confidence. Candidates presented their *manifestos and promises*, highlighting their vision to improve different aspects of school life. Through speeches, posters, and campaign activities, students confidently voiced their ideas while learning the values of democracy, responsibility, and teamwork.', '68e3ade8195b0.jpeg', '2025-03-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('91', '2', 'Student Council Election Campaign 2025', 'The *Election Campaign 2025* at our school created an atmosphere of excitement, energy, and healthy competition across all sections. Students enthusiastically took part in the campaign, showcasing their leadership skills, creativity, and confidence. Candidates presented their *manifestos and promises*, highlighting their vision to improve different aspects of school life. Through speeches, posters, and campaign activities, students confidently voiced their ideas while learning the values of democracy, responsibility, and teamwork.', '68e3ae8170990.jpeg', '2025-03-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('92', '2', 'Investiture Ceremony – Eye Section', 'The Investiture Ceremony for the Eye Section was held with great enthusiasm, marking the beginning of a new journey for our youngest leaders. Students were entrusted with responsibilities as class monitors and house representatives, symbolizing the values of discipline, cooperation, and respect. The ceremony began with the oath-taking, where students pledged to carry out their duties with honesty and commitment. Badges and sashes were presented, filling the young leaders with pride and excitement. This event instilled confidence and a sense of responsibility in our little ones, inspiring them to contribute positively to their school community.', '68e3af1a10042.jpeg', '2025-02-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('93', '2', 'Investiture Ceremony – Eye Section', 'The Investiture Ceremony for the Eye Section was held with great enthusiasm, marking the beginning of a new journey for our youngest leaders. Students were entrusted with responsibilities as class monitors and house representatives, symbolizing the values of discipline, cooperation, and respect. The ceremony began with the oath-taking, where students pledged to carry out their duties with honesty and commitment. Badges and sashes were presented, filling the young leaders with pride and excitement. This event instilled confidence and a sense of responsibility in our little ones, inspiring them to contribute positively to their school community.', '68e3b0a0b9bcb.jpeg', '2025-10-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('94', '2', 'Investiture Ceremony – Senior Section', 'The Senior Section Investiture Ceremony 2025 was conducted with dignity and pride, honoring the newly elected Student Council members. The solemn occasion began with the oath-taking, where students pledged to uphold the school’s values of integrity, discipline, and service. Sashes and badges were conferred upon the council by the Principal and faculty members, signifying trust and responsibility. The Principal’s motivating address reminded students that leadership is about service, commitment, and being role models for others. The ceremony concluded with resounding applause for the student leaders, marking the start of a year filled with teamwork, vision, and responsibility.', '68e3b10655536.jpeg', '2025-10-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('95', '2', 'Friday Takeaway', 'Our Friday Takeaway is a special tradition where students pause to reflect on the week’s learning before heading home. Each Friday, children share their key lessons, values, and experiences, reinforcing concepts taught in class and connecting them with real-life situations.', '68e3b185ddd79.jpeg', '2025-10-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('96', '2', 'Teacher’s Day Celebration', 'Our school joyfully celebrated Teacher’s Day to express gratitude and admiration for the mentors who inspire, guide, and nurture students every day. The program was filled with heartfelt performances, poems, and skits presented by students to honor their teachers. The celebration created a warm and cheerful atmosphere, highlighting the invaluable role teachers play in shaping young minds and futures. Students conveyed their appreciation with handmade cards, tokens of love, and sincere words of thanks. The day was a beautiful reminder that teachers are not just educators but also role models who leave a lasting impact on their students’ lives.', '68e3b1cd9cac1.jpeg', '2025-10-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('97', '2', 'Exploring the World of Chemistry – Pre-9 Students in Action', 'Our Pre-9 students performed their Chemistry practicals with great enthusiasm today. They learned how to handle laboratory instruments carefully and prepare chemical solutions with accuracy and safety.\r\n\r\nIt was wonderful to see their curiosity and dedication as they turned theory into practice and explored the real-world side of science.', '68e4eb8f365dc.jpeg', '2025-10-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('98', '2', 'Flipped Classroom in Action – Students Become the Teachers', 'In today’s biology class, our students stepped into the role of teachers using the flipped classroom approach. They came prepared to present key concepts and lead engaging discussions.\r\n\r\nThis method helps build confidence, teamwork, and a deeper understanding of the subject. It was inspiring to see our students take charge of their learning and explain complex ideas with clarity and enthusiasm.', '68e4ec6198317.jpeg', '2025-10-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('99', '2', 'Nature Exploration – Playgroup Learners on a Leaf Hunt', 'Our curious Playgroup learners went on a little nature hunt to collect big and small leaves. With excitement in their eyes and baskets in their hands, they explored, compared, and learned to sort by size.\r\n\r\nIt was a fun-filled, hands-on activity that helped them observe, think, and discover the beauty of nature.', '68e5016a14523.jpeg', '2025-10-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('100', '2', 'Little Explorers on a Wild Adventure', 'Today, our curious nursery learners explored the amazing worlds of animals — from the deep blue sea to the heart of the jungle. They discovered creatures big and small, fierce and friendly, learning through fun activities, stories, and laughter.\r\n\r\nEvery day is a new adventure when learning is filled with wonder!', '68e5350630ef1.jpeg', '2025-10-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('101', '2', 'Exploring Constitutional Evolution: A Comparative Study', 'Class 10 students delved into an insightful comparative study of the 1952 and 1956 Constitutions, engaging deeply with the historical and political contexts of each. Through collaborative discussions and analytical activities, they skillfully highlighted the key similarities and distinctions between the two, demonstrating a mature understanding of constitutional development. The session not only enriched their knowledge but also fostered critical thinking, teamwork, and a deeper appreciation of the evolution of governance.', '68e66fc3dd84d.jpeg', '2025-10-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('102', '2', 'Tiny Thinkers at Work: Solving Number Puzzles Together!', 'Our little learners from Playgroup worked together in peer groups to solve an exciting number puzzle! With cheerful teamwork and curiosity, they matched numbers, counted carefully, and supported one another every step of the way. This fun-filled activity not only strengthened their number recognition and problem-solving skills but also taught them the importance of cooperation and working together.', '68e6707d935cf.jpeg', '2025-10-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('103', '2', 'Birthday Celebration for Musa Hassan', 'Our Nursery class celebrated the special day of our little star, Musa Hassan. The celebration was filled with laughter, joy, and sweet treats, bringing smiles to everyone’s faces. We wish Musa a very happy birthday and hope his days are as bright and cheerful as today.', '68e67160a7f9e.jpeg', '2025-10-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('104', '1', 'Upcoming Spelling Competition', 'We are delighted to announce an upcoming Spelling Competition for our students. The elementary round will take place during the weekly dictation sessions conducted by the English Language teachers. From each class, five students will qualify for the Semi-Qualifier Round after the completion of three dictation sessions.', '68e6724167aae.jpeg', '2025-10-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('105', '1', 'World Animal Day Celebration', 'Our early years’ learners at SKANS will be celebrating World Animal Day with great excitement and curiosity. The day will be filled with engaging and hands-on activities designed to help children learn about different animals, their habitats, and the importance of caring for them.\r\n\r\nStudents will share information about their favorite animals, and some will even bring their real pets to school, making the celebration both meaningful and memorable. Through songs, stories, and creative tasks, our little learners will explore the values of empathy, kindness, and love for all living creatures.\r\n\r\nThis special day will encourage children to understand the importance of protecting animals and appreciating the beautiful diversity of life around us.', '68e8718a9c18e.jpeg', '2025-10-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('106', '1', 'NB Maintenance Workshop', 'An NB Maintenance Workshop will be conducted at SKANS to enhance teachers’ understanding of effective notebook management and academic presentation. The session will focus on maintaining consistency, clarity, and quality in students’ written work, along with the importance of constructive feedback and feedforward remarks.\r\n\r\nTeachers will engage in meaningful discussions, share best practices, and reflect on strategies to ensure that notebooks serve as a clear record of students’ progress and learning journey.\r\n\r\nThe workshop will further reinforce SKANS’ commitment to maintaining high academic standards and promoting continuous professional development, ensuring excellence in every classroom.', '68e871dd024b7.jpeg', '2025-10-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('107', '1', 'INSET 2025–26: Empowerment in Motion', 'INSET 2025–26 session titled “Empowerment in Motion” will be held at SKANS to mark the beginning of another year of learning, growth, and professional excellence. The session will bring together passionate educators to engage in collaborative discussions, reflective practices, and innovative training experiences.\r\n\r\nIt will focus on empowering teachers with new strategies, ideas, and insights that foster creativity and excellence in the classroom. The theme “Empowerment in Motion” symbolizes progress, continuous improvement, and the shared commitment to nurturing confident and capable learners.\r\n\r\nThe workshop will set a positive tone for the academic year, reinforcing SKANS’ vision of excellence through collaboration, inspiration, and empowerment.', '68e87244aa90d.jpeg', '2025-10-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('108', '2', 'Playgroup EPL Learning', 'At SKANS, our Playgroup learners are joyfully engaged in Exercises of Practical Life (EPL) — simple yet purposeful activities that nurture independence, coordination, and confidence from an early age.\r\n\r\nThrough hands-on experiences like pouring, sorting, buttoning, and cleaning, children develop essential life skills while learning to care for themselves and their environment. These activities help refine motor control, build concentration, and foster a sense of responsibility.\r\n\r\nEPL learning encourages our little ones to explore, act independently, and take pride in their achievements — making learning both meaningful and enjoyable.', '68e90dff2a236.jpeg', '2025-10-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('109', '2', 'INSET 2025–26: Empowerment in Motion', 'The INSET 2025–26 session titled “Empowerment in Motion” will be held at SKANS to mark the beginning of another year of learning, growth, and professional excellence. The session will bring together passionate educators to engage in collaborative discussions, reflective practices, and innovative training experiences.\r\n\r\nIt will focus on empowering teachers with new strategies, ideas, and insights that foster creativity and excellence in the classroom. The theme “Empowerment in Motion” symbolizes progress, continuous improvement, and the shared commitment to nurturing confident and capable learners.\r\nThe workshop will set a positive tone for the academic year, reinforcing SKANS’ vision of excellence through collaboration, inspiration, and empowerment.', '68e9076e5a06e.jpeg', '2025-10-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('110', '2', 'Animal Day Celebration', 'Our little learners joyfully celebrated Animal Day with great excitement and curiosity! The day was filled with engaging activities that helped children learn about different animals, their habitats, and the importance of caring for them.\r\n\r\nStudents enthusiastically shared interesting facts about their favorite animals and some even brought real pets to school, creating a wonderful learning experience for everyone. Through these fun-filled activities, our young learners developed empathy, love, and responsibility towards animals.\r\n\r\nIt was truly a delightful day celebrating the beautiful bond between humans and animals!', '68ebbde8bc822.jpeg', '2025-10-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('111', '2', 'Wall of Honour Assembly', 'SKANS proudly held its Wall of Honour Assembly, recognizing students who have shown outstanding performance and exemplary behavior in various areas. The event celebrated our young achievers for their consistent effort, discipline, and dedication.\r\n\r\nStudents were awarded titles such as Courtesy King and Queen, Best Reader, Best in Uniform, Best in Discipline, Best Artist, Language Expert, and IT Wizard. Each award reflected the students’ unique talents and commitment to excellence.\r\n\r\nThe assembly not only highlighted their achievements but also inspired others to strive for their best. Congratulations to all our shining stars who made it to the Wall of Honour!', '68ebbfc25265f.jpeg', '2025-10-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('112', '2', 'Notebook Maintenance Workshop', 'Senior school teachers conducted an engaging workshop for Grades Pre-9, 9, and 10 to guide students on maintaining exemplary notebooks. \r\nDuring the session, model notebooks were displayed to demonstrate proper layout, neat presentation, and organized work. Teachers highlighted essential practices such as using clear headings, proper margins, and overall cleanliness.\r\nStudents participated enthusiastically and later shared thoughtful reflections on the importance of well-maintained notebooks. \r\nThe workshop concluded with students feeling motivated and inspired to apply these practices and elevate the standard of their academic work.', '68ef8a6b2cc91.jpeg', '2025-10-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('113', '2', 'Fun with Number 4!', 'Fun with Number 4! Our little mathematicians of Playgroup enjoyed a dot painting activity to learn and recognise the number 4! \r\nThey dipped their brushes in bright colours and joyfully painted each dot, strengthening their fine motor skills while reinforcing number recognition. \r\nLearning numbers has never been this colourful and fun!', '68ef8b95bee8f.jpeg', '2025-10-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('114', '2', 'KG Shared Reading Session', 'Our Kindergarteners had a delightful time during their Shared Reading Session. Sitting together, they explored colourful storybooks, discussed characters, and shared their favourite parts with friends.\r\n\r\nThrough this joyful activity, our little readers are not only developing early reading skills but also learning to listen, imagine, and express themselves confidently.\r\nEvery page turned today brought them one step closer to becoming lifelong lovers of books.', '68ef8cac333a8.jpeg', '2025-10-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('115', '2', 'Inter-School Parliamentary Style Debates – School Round', 'Our senior students showcased exceptional confidence and critical thinking during the Parliamentary Style Debates – School Round! \r\nWith powerful arguments, teamwork, and respectful rebuttals, they demonstrated the art of persuasive speaking and intellectual exchange.', '68efcf1a2acdd.jpeg', '2025-10-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('116', '2', 'Family Tree Activity', 'Our Nursery little learners joyfully explored the theme of family by creating their very own Family Trees. \r\nThrough this engaging hands-on activity, children learned about family relationships, love, and belonging. It was heartwarming to see their excitement as they proudly shared pictures of their family members and decorated their trees with creativity and care.', '68efd04e98ad4.jpeg', '2025-10-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('117', '2', 'Assembly Presentation on Respect', 'Our little stars from KG-B beautifully presented their assembly on “Respect.” Through heartwarming messages, they reminded everyone that kindness and respect make our world a better place!', '68efd148ddf7d.jpeg', '2025-10-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('118', '2', 'Learning Number 10 through a Creative Activity', 'Our little artists from Nursery class enjoyed a fun-filled learning experience as they decorated their notebooks beautifully. The activity involved pasting ten circles on mushrooms, helping children reinforce the concept of the number 10 in an engaging and creative way. Through this hands-on task, students not only strengthened their number recognition skills but also expressed their creativity with enthusiasm and joy.', '68efd25b13b2f.jpeg', '2025-10-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('119', '1', 'Inter-School Parliamentary Style Debates Competition – October 22', 'SKANS is all set to host the Inter-School Parliamentary Style Debates Competition on October 22. This exciting event will bring together talented debaters from various schools to engage in thought-provoking discussions and showcase their public speaking skills. The competition aims to promote critical thinking, confidence, and respectful communication among students, providing them with a platform to express their ideas with clarity and conviction.', '68efd317e17a8.jpeg', '2025-10-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('120', '1', 'Inter-School Girls Shuttle Tournament – Happening Tomorrow', 'SKANS is gearing up for the Inter-School Girls Shuttle Tournament taking place tomorrow. The event will bring together enthusiastic participants from various schools, ready to showcase their agility, teamwork, and sportsmanship on the court. This tournament aims to promote physical fitness, confidence, and healthy competition among young athletes. Everyone is eagerly looking forward to an exciting day filled with energy, determination, and school spirit.', '68efd3fc9152b.jpeg', '2025-10-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('121', '2', 'Trophy Comes Home!', 'Our campus proudly clinched 1st position in the Badminton Match, bringing the trophy home with determination, teamwork, and spirit! Each player showcased incredible skill, sportsmanship, and perseverance throughout the tournament.\r\n\r\nThe victory truly reflects our motto of “Empowerment in Motion” — inspiring our learners to excel not only in academics but also in co-curricular pursuits.\r\n\r\nCongratulations to our champions!', '68f5952ace630.jpeg', '2025-10-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('122', '2', 'Girls’ Shuttle Tournament', 'Our talented young athletes showcased their energy, focus, and sportsmanship in the Girls’ Shuttle Tournament held at our campus! The matches were filled with thrilling rallies, teamwork, and determination as each player gave her best on the court.\r\n\r\nIt was truly inspiring to see our girls display confidence, strength, and the spirit of healthy competition — proving that empowerment is always in motion at SKANS!', '68f595cd3429f.jpeg', '2025-10-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('123', '2', 'World Food Day Celebration at EYE!', 'Our little learners at the Early Years Environment (EYE) celebrated World Food Day with excitement and curiosity! The day was filled with fun, learning, and delicious discoveries as children explored different food groups and understood the importance of healthy eating and avoiding food waste.\r\n\r\nThrough interactive discussions, creative art activities, and tasting experiences, our young ones learned how food nourishes our bodies and brings people together.\r\n\r\nTogether, we celebrated the joy of food and gratitude for every meal!', '68f5961e5b9da.jpeg', '2025-10-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('124', '2', 'EYE INSET: Empowerment in Motion', 'At SKANS, we believe that empowered teachers create empowered learners. Our Early Years Educators came together for an enriching INSET session titled “Empowerment in Motion” — a day filled with learning, collaboration, and reflection.\r\n\r\nThe session focused on innovative teaching strategies, classroom management, and ways to nurture creativity and critical thinking in young learners. Teachers engaged in hands-on activities and meaningful discussions, reigniting their passion for early childhood education.\r\n\r\nWith renewed energy and shared purpose, our team continues to move forward — empowered, inspired, and in motion!', '68f59681d4abb.jpeg', '2025-10-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('125', '2', 'Learning Safety Rules in Class!', 'Our little learners discovered how to stay safe and smart in the classroom.\r\nThey learned to walk carefully, keep hands to themselves, and use things gently.\r\nWith cheerful smiles and kind hearts, they promised to follow safety rules every day!', '68f9829473b9e.jpeg', '2025-10-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('126', '2', 'ح کی بناوٹ', 'آج پلیے گروپ کے ننھے منھے بچوں نے رنگ برش اور چمکدار موتیوں ???? کی مدد سے حرف &quot;ح&quot; کی خوبصورت بناوٹ سیکھی۔\r\nبچوں نے بڑے جوش و خروش اور دلچسپی کے ساتھ حصہ لیا اور اپنی تخلیقی صلاحیتوں کا بھرپور مظاہرہ کیا۔\r\nسرکل ٹائم میں بچوں نے ریت پر حروف کی لکھائی کی مشق بھی کی، جس سے ان کی تحریری مہارت میں مزید نکھار آیا۔', '68f9834ca9b45.jpeg', '2025-10-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('127', '2', 'Circle Time Highlights', 'From lively GPC drills that sharpened our letter-sound skills, to joyful rhymes and our little learners if Nursery class sharing big thoughts during news time — every moment was filled with fun, learning, and confident voices!', '68f983dacea65.jpeg', '2025-10-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('128', '2', 'پھلوں کا رنگا رنگ دن', 'ہمارے ننھے منھے بچوں نے مختلف پھلوں کے نام سیکھے اور اپنے پسندیدہ پھل کے بارے میں بات کی۔ سب نے بہت خوشی اور دلچسپی کے ساتھ حصہ لیا، کلاس پھلوں کی خوشبو اور مسکراہٹوں سے بھر گئی!', '68f984d832b10.jpeg', '2025-10-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('129', '2', 'Inter-School Parliamentary Style Debates', 'Our SKANS School System, Airport Campus, proudly hosted the Inter-School Parliamentary Style Debates — an engaging event that brought together brilliant young minds from various campuses. The competition provided students with a platform to express their opinions, think critically, and showcase their public speaking skills with confidence and poise. Each participant demonstrated remarkable clarity, teamwork, and analytical thinking throughout the sessions. The event reflected our commitment to nurturing confident communicators and future leaders. Congratulations to all the participants for their outstanding performances and spirited participation!', '68f9898152651.jpeg', '2025-10-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('130', '2', 'Exploring Long and Short Vowel /a/ Sounds', 'Our kindergarteners joyfully explored the long and short vowel /a/ sounds through exciting sorting games and interactive activities. The hands-on learning experience kept them engaged as they identified, sorted, and practiced vowel sounds in a fun and meaningful way — making phonics come alive in the classroom!', '68fada14db26f.jpeg', '2025-10-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('131', '2', 'Circle Time Fun with Numbers, Phonics, and Stories!', 'Today our little learners enjoyed an exciting circle time filled with numbers, phonics, and an Urdu story. From counting and sounds to storytelling, the session was packed with learning, laughter, and endless fun.', '68fadaa4e7177.jpeg', '2025-10-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('132', '2', 'Leafy Laughs Day', 'The learners had a wonderful time exploring and creating with leaves. They enjoyed sorting and pasting big leaves like giants and tiny ones like babies, laughing as they worked and comparing shapes and textures. The classroom was filled with joy, sticky fingers, and bright conversations about nature.\r\n\r\nThis hands-on activity helped develop their fine motor skills, observation, and creativity. By using natural materials, the learners connected with the outdoors, practiced careful handling, and celebrated the simple joy of making art together. The result was a beautiful, leaf-filled display reflecting their proud efforts and discoveries.', '68fe6062c6f3f.jpeg', '2025-10-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('133', '2', 'Friday Takeaways', 'Our kindergarten learners created beautiful Gratitude Jars as part of their moral development activity. They shared the blessings they are thankful for and reflected on the importance of gratitude in everyday life. Through this meaningful experience, they learned to always thank Allah for His countless favors and to appreciate the little things that make them happy.', '68fe609eb1e0c.jpeg', '2025-10-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('134', '2', 'Exploring Pakistan’s Provinces', 'Class 1 learners had a hands-on experience exploring the provinces of Pakistan using a map board. They identified and located each province, learning about their names and positions on the map. This interactive activity helped strengthen their geographical understanding and made learning both engaging and memorable.', '68fe6133f1a79.jpeg', '2025-10-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('135', '2', 'Parent-Teacher Meeting', 'A Parent-Teacher Meeting was held to discuss students’ progress, achievements, and areas for improvement. Parents had the opportunity to review their child’s work, share feedback, and celebrate their learning journey. The meeting fostered strong collaboration between parents and teachers, ensuring continued support for each learner’s growth and development.', '68fe6181e06d5.jpeg', '2025-10-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('136', '2', 'Connecting Through Conversation', 'Our Parent-Teacher Meeting with the Principal provided a meaningful platform for parents and teachers to come together and discuss students’ academic and personal growth. The Principal emphasized the importance of collaboration between home and school, encouraging parents to stay engaged in their children’s learning journey.\r\nThe session fostered open communication, mutual understanding, and a shared commitment to supporting every learner’s success.', '68fe625982973.jpeg', '2025-10-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('137', '2', 'Courtesy Kings and Queens &amp; Wall of Honour Assembly', 'Our school proudly celebrated the Courtesy Kings and Queens and Wall of Honour Assembly, recognizing students who displayed outstanding manners, respect, and kindness throughout the month. Learners were appreciated for their positive attitude, helpfulness, and courteous behavior towards peers and teachers.\r\n\r\nThe Wall of Honour showcased students who excelled academically and behaviorally, serving as role models for their classmates. The celebration aimed to promote good values, motivate students to always be polite and respectful, and highlight the importance of character alongside achievement.', '68fe62bab290e.jpeg', '2025-10-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('139', '2', 'Poppin’ Sounds and Smart Learning Day', 'Today our little learners turned into sound scientists as they explored blending sounds in the most fun way possible!\r\nWith colorful poppin’ tubes in their hands, every pop came with laughter and excitement — helping them join letter sounds together like magic.\r\nThey also enjoyed a lively video session that made blending sounds feel like a musical adventure. It was a day full of pops, giggles, and smart learning!', '690171278f854.jpeg', '2025-10-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('140', '2', 'The Whirl of Autumn Wonders at EYE', 'Our Early Years learners joyfully celebrated “The Whirl of Autumn” — a day filled with color, creativity, and connection to nature! \r\nFrom leaf art and seasonal crafts to engaging games and rhymes, children explored the beauty of autumn while expressing gratitude for Allah’s countless blessings. Their laughter, curiosity, and excitement turned the day into a heartwarming celebration of learning through play.', '69017177609c5.jpeg', '2025-10-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('141', '2', 'Celebrating Autumn with a big heart!', 'Little hearts full of joy and gratitude! \r\nOur tiny learner beautifully filled the heart with autumn love and colors of the season.', '690171ba24095.jpeg', '2025-10-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('142', '2', 'Stand Up, Speak Out: Anti-Bullying Awareness', 'Today, our talented Class 10 students delivered a powerful Anti-Bullying Skit that shed light on verbal, social, and physical bullying. Their impactful performance reminded everyone to take a stand against bullying and to promote kindness, respect, and empathy within our school community.', '69017350ce587.jpeg', '2025-10-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('143', '2', 'Class 1-A Assembly on United Nations', 'Our young learners of Class 1-A beautifully presented an informative assembly on the United Nations, highlighting the importance of peace, unity, and cooperation among nations.', '6902bddd3cc41.jpeg', '2025-10-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('144', '2', 'Shapes Man Visits Nursery Class', 'Our Nursery class had a fun-filled learning experience as they met the colorful and jolly Shapes Man today! He helped the little learners explore the circle, square, triangle, and rectangle in an exciting and interactive way.\r\n\r\nThe children sang songs, danced, and eagerly pointed out shapes they could see around them. It was delightful to watch their enthusiasm and confidence as they recognized and named each shape.\r\n\r\nLearning about shapes turned into a joyful adventure — all thanks to our cheerful Shapes Man who made the lesson both fun and memorable!', '69040f2d8e1bf.jpeg', '2025-10-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('145', '2', '“د” (دال) کی جادوئی دنیا&quot;', 'آج سرکل ٹائم میں ہمارے ننھے منے بچوں نے جادوئی ڈبے سے وہ چیزیں نکالیں جو “د” (دال) سے شروع ہوتی تھیں — جیسے دودھ، دانت، دلیا، درخت وغیرہ! سب نے باری باری چیزیں پہچانیں تو کلاس میں خوشی کی لہر دوڑ گئی۔\r\n\r\nپھر آیا سب کا پسندیدہ حصہ — دُنبا کرافٹ!\r\nبچوں نے روئی چپکا کر اپنے دنبے اتنے پیارے بنائے کہ سب کے چہروں پر مسکراہٹ آ گئی۔ کچھ دنبے موٹے، کچھ دبنگ، اور سب ہی نرالے۔\r\n\r\nآخر میں سب نے مل کر “د” کی آواز دہرائی۔\r\nواقعی آج کا دن مزے، ہنسی اور سیکھنے سے بھرپور تھا۔', '6908063f2b983.jpeg', '2025-10-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('146', '2', 'Class 1B Assembly on “Stop Bullying”', 'Our young learners of Class 1B confidently presented an assembly on the important theme “Stop Bullying.” Through short acts and meaningful messages, they spread awareness about kindness, respect, and standing up for others. It was a thoughtful and inspiring presentation, reminding everyone that a little kindness goes a long way!', '69080691e6e48.jpeg', '2025-10-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('147', '2', 'Exploring Patterns with 2D Shapes in Class 1', 'Our creative learners from Class 1 enjoyed an exciting hands-on math activity today! They explored 2D shapes by creating colorful and interesting patterns using circles, squares, triangles, and rectangles.\r\n\r\nThe children arranged the shapes in different sequences and discovered how repeating patterns can be made in fun and unique ways. It was wonderful to see their creativity shine as they experimented with shapes and colors — turning a simple math concept into an engaging art experience!', '690806f1ca4ae.jpeg', '2025-10-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('148', '2', 'Friday Takeaway Fun — P for Penguin!', 'Our little learners in playgroup had an exciting time making the “P for Penguin” craft today! They enjoyed cutting, pasting, and creating their adorable chilly friends while learning the sound of the letter Pp. It was a perfect blend of creativity and learning — turning phonics into a fun, hands-on experience!', '69080740950ea.jpeg', '2025-10-31');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('149', '2', 'Learning the Concept of Time!', 'Our kindergarteners explored the concept of time through engaging discussions and interactive activities. They learned to identify different parts of the day and relate daily routines to morning, afternoon, and evening — making time-telling a fun and meaningful learning experience!', '690807946c914.jpeg', '2025-10-31');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('150', '2', 'A Joyful Day at Joyland!', 'Our Class 3–6 students had an unforgettable day at Joyland — filled with laughter, excitement, and endless fun! From thrilling rides to shared giggles, it was truly a day to remember.', '690c2870b0d30.jpeg', '2025-11-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('151', '2', 'Play, Learn, and Grow — EYE Trip to WePlay!', 'Our Early Years learners spent a delightful day at WePlay, engaging in fun activities that encouraged imagination, creativity, and cooperation.', '690c28de112ad.jpeg', '2025-11-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('152', '2', 'Exploring Weather with Creativity!', 'As part of their Friday takeaway activity, our kindergarten students crafted different types of weather, showcasing their creativity and understanding of the topic. It was a fun and engaging way to reinforce their learning through hands-on exploration!', '69113a97dff83.jpeg', '2025-11-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('153', '2', 'Tribute to Allama Iqbal', 'Today, our students paid a heartfelt tribute to Allama Iqbal through inspiring speeches, soulful performances, and meaningful role plays that brought his poetry and vision to life. The celebration beautifully reflected the spirit of Iqbal’s timeless message — “Khudi ko kar buland itna…”', '69113b3cc555c.jpeg', '2025-11-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('154', '2', 'A POP-tastic Day in Playgroup!', 'Our little popcorn makers of Playgroup had a fun-filled day learning the letter P through a hands-on popcorn activity. Using playdough, they rolled, pressed, and popped their way to creativity and learning. It was a delightful experience full of laughter, excitement, and imagination — turning learning into a true popcorn party!', '69113b83cb465.jpeg', '2025-11-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('155', '2', 'Shared Reading — The Land of the Dinosaurs', 'Students of Class 1 participated in a shared reading session of the ORT story The Land of the Dinosaurs to enhance their reading skills. Through guided reading and engaging discussions, they practiced pronunciation, fluency, and comprehension. The captivating storyline and colorful illustrations kept them motivated, helping them build vocabulary and develop a lifelong love for reading.', '69113bca9770b.jpeg', '2025-11-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('156', '2', 'Circle Time Fun at SKANS!', 'Circle time makes learning fun! Numbers, Haroof, and GPC drills — our little stars are growing brighter every day as they learn, explore, and shine through engaging activities.', '69113c2e6044e.jpeg', '2025-11-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('157', '2', 'A Day Full of Fun and Adventure at Nathia Gali!', 'What an amazing and refreshing day our students had at Nathia Gali! From scenic views to engaging activities, every moment was filled with joy, learning, teamwork, and wonderful memories. Students from Classes 6 to 10 enjoyed nature walks, fun interactions, group activities, and endless laughter throughout the trip.', '69113dc34d60b.jpeg', '2025-11-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('158', '1', 'Proud Moment for SKANS!', 'We are delighted to announce that our brilliant student, Eshaal Zafar, has achieved an outstanding milestone by ranking among the top 500 nationwide, securing the 141 position in the National Mathematics Talent Contest 2025.\r\nHer remarkable performance is a true reflection of dedication, perseverance, and excellence — values we proudly nurture at SKANS School System. Congratulations, Eshaal, for making your school proud!', '69113e12a734f.jpeg', '2025-11-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('159', '1', 'Proud Achievement — SKANS School AECHS Campus', 'We are proud to announce that our students have excelled in the Pakistan Math Contest. Abeer Fatima secured the highest percentage across SKANS campuses, Abdul Mueed earned the second-highest percentage and has advanced to the second phase, and Mustafa Adnan also qualified for the next round. Congratulations to our young mathematicians on their hard work and dedication.', '69138b15c114b.jpeg', '2025-11-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('160', '1', 'Proud Achievement — SKANS School AECHS Campus', 'We are proud to announce that our students have excelled in the Pakistan Math Contest. Abeer Fatima secured the highest percentage across SKANS campuses, Abdul Mueed earned the second-highest percentage and has advanced to the second phase, and Mustafa Adnan also qualified for the next round. Congratulations to our young mathematicians on their hard work and dedication.', '69138dcf3a356.jpeg', '2025-11-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('161', '1', 'Proud Achievement — SKANS School AECHS Campus', 'We are proud to announce that our students have excelled in the Pakistan Math Contest. Abeer Fatima secured the highest percentage across SKANS campuses, Abdul Mueed earned the second-highest percentage and has advanced to the second phase, and Mustafa Adnan also qualified for the next round. Congratulations to our young mathematicians on their hard work and dedication.', '69138e5614b15.jpeg', '2025-11-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('162', '2', 'Math Project Display!', 'Numbers, logic, and creativity beautifully came together today as our students presented their Math Project Display! \r\nEach project was thoughtfully designed to show how Math can be fun, meaningful, and full of imagination. Students confidently explained their ideas and demonstrated how Math connects to real-life situations through engaging games and activities. It was truly a celebration of curiosity and learning!', '69138eb6ca722.jpeg', '2025-11-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('163', '2', 'Grateful hearts, busy hands!', 'Our little ones from class 1 crafted thank-you cards for the heroes who grow our food — our amazing farmers!', '69138ef9d3c51.jpeg', '2025-11-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('164', '2', 'Sorting Healthy and Junk Food Activity', 'Our little learners of play group had a fun and engaging activity today!  They sorted different food items into healthy and junk categories.  Through this hands-on experience, children learned to identify foods that help us grow strong  and those we should eat only sometimes.', '69138fac23bd2.jpeg', '2025-11-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('165', '2', 'Bringing “The Very Hungry Caterpillar” to Life!', 'Our little learners transformed the beloved story “The Very Hungry Caterpillar” into a delightful role play performance. From the tiny caterpillar munching through fruits to the beautiful butterfly spreading its wings, the children wonderfully expressed the story’s magic and its message of growth and transformation. The activity was a joyful learning experience filled with colors, creativity, and confidence.', '6914d3c404f5f.jpeg', '2025-11-12');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('166', '2', 'Our Little Tech Explorers in the ICT Lab', 'Our little tech explorers visited the ICT lab and enjoyed typing their names in MS Word. Learning to use technology gave them the experience of being mini professionals.', '6914d441b17bf.jpeg', '2025-11-12');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('167', '2', 'Measuring Length – An Interactive Learning Experience', 'Our Class 1 learners participated in an engaging Mathematics activity focused on measuring length. Students explored various objects at the action table, discussed concepts like “long” and “short” during circle time, and completed an interactive worksheet with enthusiasm. It was a meaningful and enjoyable learning experience for our young learners.', '691a7c3eaa28a.jpeg', '2025-11-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('168', '2', 'نیلا دن — بچوں کی نیلی دنیا کا حسین سفر', '2. \r\nآج ہمارے ننھے سیکھنے والوں نے نیلا دن بھرپور جوش و خروش کے ساتھ منایا۔ سمندری مخلوق، تخلیقی سرگرمیوں اور کھلی فضا میں مشاہدے نے اس دن کو مزید یادگار بنا دیا۔ بچوں نے رنگوں کی پہچان، تخیل اور گفتگو میں بھرپور حصہ لیا اور نیلے رنگ کے جادو نے اُن کا دن خاص بنا دیا۔', '691a7c9cc14a1.jpeg', '2025-11-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('169', '2', 'World Kindness Day', 'Our Class 1 learners filled their Kindness Jars with thoughtful good deeds, adding warmth and positivity to the classroom environment. Each jar beautifully reflected their caring hearts and genuine efforts to show empathy and respect. Kindness was not just taught—it was lived and practiced throughout the activity.', '691a7cd9aa558.jpeg', '2025-11-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('170', '2', 'Our Students’ Curious Minds at Work', 'Our students are actively engaged in exploring ideas and sharing thoughtful responses during the Big Question activity. This experience supports critical thinking, meaningful discussion, and helps deepen their understanding of the topic.', '691a7dc1cee6b.jpeg', '2025-11-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('171', '2', 'جماعت نہم — عام الوفود کے موضوع پر', 'جماعت نہم کے طلباء نے عام الوفود کے موضوع پر کے ڈبلیو ایل چارٹ کامیابی سے مکمل کیا۔ طلباء نے اپنی سابقہ معلومات، سیکھنے کے سوالات، اور حاصل کردہ نئی معلومات کو نہایت منظم انداز میں تحریر کیا۔ یہ سرگرمی ان کی سوچ، تحقیق اور سمجھ میں نمایاں بہتری کا سبب بنی۔', '691a7ec1da0da.jpeg', '2025-11-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('172', '2', 'Community Helpers!', 'Today our kindergarten stars stole the show with their wonderful presentations on Community Helpers! \r\nDressed up in adorable professional get-ups, each child confidently spoke about their chosen role. \r\nA special highlight was having their mothers join us — watching their little ones shine and creating beautiful art and craft pieces together. \r\nWe extend our heartfelt thanks to all the mothers who joined us today, and to those who couldn’t attend but dressed their children so beautifully and supported them from home — your efforts truly made the day special. It was an amazing  heartwarming experience filled with learning and fun.', '691cb8117ff40.jpeg', '2025-11-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('173', '1', '“Bullying and Its Effects”', 'We are pleased to inform you that Umar Tarar from Youth Club will be joining us tomorrow for a motivational workshop on “Bullying and Its Effects.”\r\n\r\nThis session will provide students with valuable insights into the impact of bullying, ways to respond positively, and strategies to foster kindness, empathy, and confidence within our school community.\r\nWe look forward to an engaging and meaningful session.', '691cb868f17b8.jpeg', '2025-11-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('174', '2', 'Motivational workshop on Bullying and Its Effects.', 'Today, our students attended an inspiring anti-bullying motivational session conducted by the amazing Youth Club Team. We are truly grateful to our special guest motivational speaker for engaging our children with powerful reminders about kindness, empathy, and good character.\r\n✨ We hope, expect, and pray that Insha’Allah these sessions will guide our students to adopt positive habits, treat each other with respect, and say NO to bullying—always.\r\nThank you to the Youth Club Team for this impactful and meaningful session. \r\nTogether, we can create a safe, caring, and respectful school environment.', '691cb8c14760b.jpeg', '2025-11-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('175', '2', 'اردو لغت', 'دلچسپی سے اپنی چھوٹی اردو لغت تیار کی، جو الفاظ کی دنیا میں ان کے خوبصورت سفر کی جھلک پیش کرتی ہے۔ ننھے معماروں نے نہ صرف الفاظ کو جمع کیا بلکہ ان کے معانی کو بھی اپنے انداز میں درج کیا، جس سے ان کی زبان دانی اور تخلیقی صلاحیتوں میں اضافہ ہوا۔ اپنی بنائی ہوئی یہ ڈکشنری بچوں کی سیکھنے کی لگن، محنت اور خود اعتمادی کی بہترین مثال ہے', '691cb9a847e96.jpeg', '2025-11-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('176', '2', 'Peg the Shirts – Number Sequencing Fun!', 'Today, our little learners of playgroup enjoyed a hands-on math activity where they practiced number sequencing in the most playful way!', '691cb9f8a4330.jpeg', '2025-11-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('177', '2', 'Exploring Earth!', 'Today, our Grade 1 learners explored our dearest homeland—Earth! \r\nThey discovered the Equator, the Northern and Southern Hemispheres, and also learned about the 7 continents using the globe.\r\nCuriosity, excitement, and learning—all in one day!', '691cba8b28922.jpeg', '2025-11-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('178', '2', 'Exploring the structure of an atom.', 'Grade 7 students are exploring the structure of an atom today! They are actively building models to understand protons, neutrons, and electrons, bringing abstract science concepts to life through hands-on learning.', '691cbae0225dd.jpeg', '2025-11-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('179', '2', 'CVC Words Activity — Playgroup Fun!', 'Our little learners enjoyed a hands-on CVC word-building activity using picture cards and alphabet tiles. Children looked at each picture (tap, sit, pan, tin, nap) and blended beginning, middle, and ending sounds to build the corresponding words.\r\nThis activity helped them strengthen phonics skills, practice sounds, improve picture–word association, and develop fine motor control. Our tiny readers proudly matched each word with its picture, showing growing confidence.', '6923334789fb9.jpeg', '2025-11-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('180', '2', 'Spell Galaxy Highlights', 'Our students delivered an impressive performance at the Spell Galaxy event! Learners from Class 1 to Class 7 participated confidently in class-based challenges, level rounds, and a thrilling tiebreaker finale. Their enthusiasm, teamwork, and strong spelling skills made the event truly memorable.', '69233396e98fe.jpeg', '2025-11-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('181', '2', 'Celebrating Our Spell Galaxy Winners', 'Our winners proudly received their certificates and medals, reflecting their hard work, confidence, and dedication. We are proud of each achiever and encourage them to keep reaching for the stars. Their success is an inspiration to all learners.', '692333df661e8.jpeg', '2025-11-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('182', '2', 'Physical Education &amp; Taekwondo Session', 'Students enjoyed an energetic session focused on fitness, focus, discipline, flexibility, and confidence. Through each activity, they strengthened their bodies and minds, developing resilience, concentration, and healthy habits.', '6923341f6edeb.jpeg', '2025-11-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('183', '2', 'Exploring Precision in the Science Lab', 'Exploring Precision in the Science Lab\r\nOur Pre-9th students explored the use of screw gauges and vernier calipers to measure tiny objects and read the smallest units on the scale. They applied these measurements to create accurate constructions, turning numbers into real shapes and ideas. The lab was buzzing with learning, teamwork, and exciting ‘wow!’ moments.', '6923346569749.jpeg', '2025-11-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('184', '2', 'Children’s Day Celebration — Early Years', 'Our Early Years children lit up the school with laughter and excitement as we celebrated Children’s Day. Creative activities and joyful moments were planned with love, and our teachers ensured that every child felt special. The day was warm, memorable, and full of smiles.', '692334b13ab1a.jpeg', '2025-11-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('186', '2', 'SSC-I &amp; SSC-II Send-Up Examinations', 'Our SSC-I and SSC-II students have begun their Send-Up Examinations. We are proud of their dedication, focus, and hard work. We wish them the very best of luck and pray for clarity, success, and excellent results.', '69233516bb6b1.jpeg', '2025-11-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('187', '2', 'Bonding Beyond Work', 'We had a wonderful day out together, filled with laughter, joy, and memories to treasure. I am proud of this incredible team—your unity, positivity, and dedication make every moment special. Here’s to many more beautiful days together, Insha’Allah!', '6923357fb428f.jpeg', '2025-11-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('188', '2', 'ننھے ستارے', 'آج ہمارے ننھے ستاروں نے اپنی چھوٹی چھوٹی سوچ کو بڑی اچھی عادتوں میں ڈھال دیا۔ \r\nمحبت، صفائی، سچائی اور احترام—سب کو خوبصورت لفظوں میں لکھا اور دل سے سچا وعدہ کیا۔\r\nبچوں کی یہ چھوٹی کوششیں ہی کل کو ایک خوبصورت شخصیت بناتی ہیں۔', '692c598cdb3ed.jpeg', '2025-11-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('189', '2', 'Learning the /s/ Sound!', 'Today, our little champs practiced the letter sound /s/ — the ssss like a friendly snake! \r\nThey wrote it on their boards and on practice strips all by themselves… feeling like big writers! \r\nSome learners made super straight s, and some made silly squiggly s — but every “s” was full of effort and cuteness!', '692c5ba4dab9d.jpeg', '2025-11-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('190', '1', 'Proud Moment for SKANS AECHS!', 'Our talented students are all set to participate in the Robotics Competition at COMSATS University!\r\nWe are thrilled to see our young innovators step forward, showcase their creativity, and represent our campus with pride.\r\nWishing them the very best, may they learn, explore, and shine! \r\nGo Team SKANS!', '692c5bf4e11f5.jpeg', '2025-11-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('191', '2', 'Play Group – Number Matching Fun!', 'Today, our little learners turned into tiny counting superheroes as they explored number recognition using colorful blocks and number cards! \r\nThey happily dipped their hands into the magic basket, grabbed silly little blocks, and matched the right number of blocks with each number card — just like mini math masters! \r\nSome counted very seriously , some counted very cutely , and some even pretended the blocks were little cars zooming to their parking spot  — but they all nailed', '692c5c9dd5f0c.jpeg', '2025-11-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('192', '2', 'Plantation Drive', 'Today, our little eco-warriors took a beautiful step towards a greener future! With bright smiles and tiny hands, they planted their very own saplings, learning the importance of caring for our Earth. \r\nMoments like these help our young learners grow with love, responsibility, and respect for nature.  \r\nTogether, we plant… together, we grow!', '692c5ce2eb15b.jpeg', '2025-11-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('193', '2', 'Strawberry Q-tip Painting Fun!', 'Today, our little artists of play group enjoyed a creative Q-tip painting activity. Using cotton buds and bright colors, they carefully dotted and decorated a happy strawberry picture. \r\nThis hands-on task helped improve their fine motor skills, focus, and color recognition.\r\nThe learners participated with great excitement and did a wonderful job!', '692c5d33000d3.jpeg', '2025-11-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('194', '2', 'Setting the table for success!', 'Our little ones of Kindergarten practiced table setting and learned the importance of good manners!', '692c855752981.jpeg', '2025-11-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('195', '2', 'Playground Safety for our little Nursery champs!', 'Today our tiny explorers learned how to play safely with big smiles and happy hearts! \r\nThey enjoyed fun activities about taking turns, using slides carefully, and being kind to friends!\r\nOur little learners practiced safe play rules through pictures, games, and giggles! \r\nTeachers also guided them on staying careful while having lots of fun! \r\nTo make learning even more fun, children cut the pictures and sorted them into Safe and Unsafe playground actions!', '692c85b0d261a.jpeg', '2025-11-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('196', '2', 'Healthy choices, happy hearts!', 'Our children created their very own healthy meal plates today—learning the importance of balanced eating while having fun!', '692c860374058.jpeg', '2025-11-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('197', '1', 'Empowering Readers, Together!', 'We are hosting an engaging Shared Reading Session for parents to demonstrate how reading strategies can build confidence, fluency, and comprehension in young learners.\r\n\r\nParents will observe practical techniques—like using picture cues, pointing, phonics support, and expression—to make reading time more meaningful and enjoyable at home.\r\n\r\nThis collaborative session will help parents understand how to support their child’s reading routine, turning every reading moment into a learning opportunity.\r\n\r\n“A child who reads is a child who grows.”', '692c89303e492.jpeg', '2025-11-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('198', '1', 'Learning Walk – A Glimpse Into Our Classrooms', 'Our upcoming Learning Walk will offer a wonderful opportunity to step inside our classrooms and witness authentic teaching and learning in action. The walk will highlight purposeful instruction, engaged learners, and thoughtfully planned activities that reflect our commitment to quality education.\r\n\r\nTeachers will showcase meaningful strategies, active learning environments, and student-centered practices that support curiosity, creativity, and critical thinking. Every corner of the school will echo with collaboration, exploration, and joyful learning.\r\n\r\nThe Learning Walk will not only celebrate our teaching standards but also strengthen our shared vision of continuous improvement and excellence.', '692c891780f42.jpeg', '2025-11-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('199', '2', 'Shared Reading Session with Parents', 'Today, our teachers demonstrated the complete Shared Reading process for parents, from start to finish, in one comprehensive and engaging session. ????✨\r\nParents observed every step live: activating prior knowledge, picture walk, vocabulary introduction, modelling fluency, expression, punctuation cues, asking guiding questions, and making meaningful connections.\r\nThe session beautifully showcased how shared reading builds comprehension, confidence, and a love for stories.\r\nA truly enriching experience that strengthened our partnership with parents.', '69323337262e0.jpeg', '2025-12-01');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('200', '2', 'Learning Walk with Parents', 'Our wonderful parents were invited on a Learning Walk, a vibrant display of student talent, effort, and progress. \r\nStudents proudly showcased their worksheets, portfolios, artwork, phonics tasks, math activities, writing pieces, and theme-based work. \r\nEvery corner reflected their learning journey, creativity, and hard work.\r\nA beautiful moment where parents witnessed real learning in action.', '6932339b3ca5b.jpeg', '2025-12-01');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('201', '2', 'Bright smiles and cheerful hearts!', 'Our little learners came together with bright smiles and cheerful hearts for their group photos. \r\nThese precious moments captured their joy, confidence, and pride after showcasing their hard work.\r\nA picture-perfect celebration of learning, growth, and togetherness.', '693234058603b.jpeg', '2025-12-01');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('203', '2', 'Today, our little explorers brought science to life!', 'Through a fun hands-on demonstration, they learned how Earth’s movement creates day and night—observing, discovering, and truly understanding the magic of our planet. After exploring their mini universe, they beautifully illustrated the entire day–night cycle in their notebooks with clarity and creativity. \r\nLittle minds, big learning!', '6932350936eeb.jpeg', '2025-12-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('204', '2', 'ORT Reading Session', 'In today’s ORT reading session, our learners explored words, spotted vocabulary, and strengthened their recognition skills. \r\nLittle readers, big progress', '6932356755cb0.jpeg', '2025-12-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('205', '2', 'Shared Reading Session – ORT Reader “Who Is It?”', 'Our little learners of play group enjoyed exploring the ORT story “Who Is It?” today! \r\nThey confidently held the book, identified the characters, and read the line “No, it’s Dad.” with excitement. \r\nThis activity helped them recognise familiar ORT characters like Dad, Mum, and Floppy, while building early reading confidence.', '693235eb0e4e6.jpeg', '2025-12-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('206', '1', 'Proud Moment for AECHS Campus!', 'Our talented students have made us shine once again!\r\nThey secured 4th position out of 26 teams in the Robotics Competition held at COMSATS University, where both universities and schools took part. \r\nWell done to our brilliant team:\r\n* Shahbaz Ul Hasan\r\n* Musa Butt\r\n* Abdullah Abbasi\r\nA big shout-out to our dedicated Robotics teacher Mr. Uzair for his guidance and support throughout the competition.\r\nWe at AECHS Campus are extremely proud of their hard work, passion, and outstanding performance.', '693236d951926.jpeg', '2025-12-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('207', '2', 'Proud Moment for AECHS Campus!', 'Our talented students have made us shine once again!\r\nThey secured 4th position out of 26 teams in the Robotics Competition held at COMSATS University, where both universities and schools took part. \r\nWell done to our brilliant team:\r\n* Shahbaz Ul Hasan\r\n* Musa Butt\r\n* Abdullah Abbasi\r\nA big shout-out to our dedicated Robotics teacher Mr. Uzair for his guidance and support throughout the competition. \r\nWe at AECHS Campus are extremely proud of their hard work, passion, and outstanding performance. Keep reaching for the stars, champions!', '6932378888d05.jpeg', '2025-12-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('208', '2', 'Exploring Earth &amp; Time with Class One!', 'Class 1 reinforced the months of the year while learning about how the Earth moves around the Sun and completes one full year. They recalled all 12 months with confidence and excitement. Then, they did an activity on Books', '6939a84921ee0.jpeg', '2025-12-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('209', '2', 'Shared Reading Session', 'Our little readers enjoyed a joyful shared reading session today!  They revisited and reinforced all their readers with confidence, expression, and excitement. Proud to see their love for reading grow each day!', '6939a8ae420c2.jpeg', '2025-12-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('210', '2', 'Art Time in Playgroup!', 'Our little artists enjoyed a colourful and creative art session today! With full focus and tiny hands at work, they explored colours and filled their artworks beautifully, showing confidence and imagination. \r\nArt class helps our young learners develop fine motor skills, creativity, colour recognition, and self-expression — and today, they shined like true little creators! Every stroke, every colour, every smile… masterpieces in the making!', '6939a942afc35.jpeg', '2025-12-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('211', '2', 'اچھی باتوں کےپھول', 'آج طلبہ نے اپنی ورکشیٹ پر اچھی باتوں کے پھول مکمل کیے، جس میں ہر پتی پر مثبت سوچ، اخلاق اور نرمی جیسے خوبصورت الفاظ لکھے۔\r\nیہ سرگرمی نہ صرف لکھائی کو بہتر بناتی ہے بلکہ بچوں کے رویے اور سوچ میں بھی خوبصورتی پیدا کرتی ہے۔ \r\n\r\nچھوٹی عمر، بڑی سوچ — یہی ہمارے ننھے ستاروں کی پہچان ہے۔', '6939a9c38044b.jpeg', '2025-12-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('212', '2', 'Pre-revision days!', 'Students of grade 5 are productively investing their pre-revision days in collaborative mid-year projects such as tense wheels and grammar dictionaries, showcasing creativity, teamwork, and independent learning.', '6939aa5b918da.jpeg', '2025-12-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('213', '2', 'Shared Reading Session!', 'Today’s reading was all about looking deeper!\r\nStudents of class 1 re-read The Treasure Chest, explored new words, and highlighted punctuation to strengthen reading fluency and understanding.', '6939abfa3148e.jpeg', '2025-12-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('214', '1', 'ORT Reading Assessment', 'Dear parents, This is to inform you that on 10th and 11th December, students will be assessed for their Reading Assessment. The reading assessment will be taken from any ORT Reader which they have read during this term, and it will be conducted by myself. \r\n\r\nTo guide you further, the assessment will be marked according to the following reading rubrics:\r\n	•	Fluency\r\n	•	Pronunciation\r\n	•	Expression\r\n	•	Comprehension\r\n\r\nWe kindly request you to support your child at home by revising all the ORT readers and encouraging regular reading practice. Your involvement will greatly help in improving confidence, clarity, and expression during reading.\r\n\r\nThank you for your cooperation.', '6939ad81cfd07.jpeg', '2025-12-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('215', '1', '5th Place (Global) in WAICY 2025', 'We are pleased to share a moment of pride for SKANS School System, AECHS Campus.\r\nOur student Sibghat Ullah has secured 5th Place (Global) in the Elementary School Category – AI-Generated Video Track at WAICY 2025 (World Artificial Intelligence Competition for Youth).\r\n\r\nThis prestigious international competition witnessed participation from over 132,000 students across 103 countries, making this achievement truly commendable. Sibghat Ullah’s success reflects his creativity, dedication, and the institution’s commitment to nurturing global-ready learners.\r\nWe extend our heartfelt congratulations to SKANS Family, Sibghat Ullah and his parents for this remarkable accomplishment.', '6946c3de661ba.jpeg', '2025-12-12');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('216', '2', 'Hands-on digital learning = happy minds + happy hearts!', 'Today, our Playgroup stars explored interactive learning games on the iPad! \r\nThey enjoyed tracing letters with their tiny fingers, building early literacy skills in a fun and engaging way. \r\nOur little champions showed great focus, creativity, and excitement as each stroke helped them grow in confidence.', '6946c4f3df91c.jpeg', '2025-12-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('217', '2', 'Mid-Year Exams 2025 began this morning', 'It was heartening to see our students enter the examination halls with confidence, calm minds, and focused expressions.\r\nWishing them continued success in the days ahead.', '6946c59d5928a.jpeg', '2025-12-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('218', '1', 'Snow Much Fun!', 'Winter Activity Day:\r\nGet ready for a day filled with winter magic, creativity, and hands-on learning!\r\nOur little learners will dive into exciting winter-themed activities where they will create, explore, experiment, and enjoy in a joyful classroom environment.\r\n\r\nFrom snowy art &amp; craft to nature collages and fun science &amp; sensory play, this special day is designed to spark imagination, curiosity, and smiles all around.', '6946c6de09490.jpeg', '2025-12-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('219', '2', 'A Day of Joy, Laughter, and Celebration', 'Our school transformed into a magical Winter Wonderland, filled with excitement and festive cheer. Students enjoyed a variety of fun-filled activities, games, and creative experiences that brought the spirit of winter to life.\r\n\r\nThe event created a joyful atmosphere where children laughed, played, and made wonderful memories with their friends and teachers. Winter Wonderland Fun was a delightful celebration that added warmth and happiness to the chilly season, making it a truly memorable day for everyone.', '6946cc1c9f4d4.jpeg', '2025-12-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('220', '2', 'Creativity in the Season of Winter', 'Students enthusiastically took part in the Winter Art and Craft activity, expressing their creativity through seasonal artwork and handmade crafts. Using winter themes, colors, and materials, they created beautiful pieces that reflected imagination and artistic skills.\r\n\r\nThe activity encouraged self-expression, fine motor development, and appreciation for art, while bringing warmth and joy to the winter season. Winter Art and Craft was a wonderful opportunity for students to explore creativity and showcase their talents.', '6946cd10e04ff.jpeg', '2025-12-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('221', '2', 'Exploring Experiments Through Hands-On Learning', 'Students enthusiastically took part in a science and sensory play activity where they experimented with salted boiled water. Using this solution, they created snowflake designs, exploring patterns and shapes through a fun, hands-on process.\r\n\r\nAs the water dried, the salt crystallized and turned white, beautifully forming snowflake-like patterns. This simple yet engaging experiment helped students understand basic scientific concepts while stimulating their senses, creativity, and curiosity.\r\nThe activity encouraged observation, experimentation, and joyful learning, making science both meaningful and memorable for our young learners.', '6946d11a7dcc0.jpeg', '2025-12-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('222', '1', 'Celebrating Creativity and Togetherness', 'The school is pleased to share the news of  the upcoming End Term Party, which will mark the joyful conclusion of the academic term. The celebration will bring students together to enjoy fun-filled activities, creativity, and togetherness.\r\nThe End Term Party aims to create a cheerful atmosphere where students can relax, celebrate their efforts, and make happy memories with their classmates and teachers.', '6946d2c574d1e.jpeg', '2025-12-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('223', '2', 'End Term Party Celebration', 'During the End Term Party, children enjoyed yummy food with their friends in a cheerful and friendly atmosphere. The shared meal added joy to the celebration, giving students a chance to relax, bond, and create happy memories together.\r\n\r\nThe event was filled with laughter and togetherness, making the end of the term a truly enjoyable experience for everyone.', '6946d4471ddac.jpeg', '2025-12-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('224', '2', 'Nose the Snowman Game', 'As part of the winter festivities, students enthusiastically participated in the Nose the Snowman game. The fun-filled activity created excitement and laughter as children took turns placing the snowman’s nose while being guided by their friends.\r\n\r\nThe game encouraged participation, coordination, and teamwork, adding joy and energy to the celebration. It was a delightful experience that brought smiles to everyone and made the event even more memorable.', '6946d51d2cc92.jpeg', '2025-12-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('225', '2', 'Hands-On Fun', 'Students enjoyed a session of hands-on fun, engaging in interactive activities that encouraged creativity, participation, and learning by doing. The activities created an energetic and joyful atmosphere, allowing children to explore, experiment, and express themselves freely.\r\n\r\nThe experience promoted active learning, teamwork, and confidence, making it a meaningful and enjoyable part of the school day.', '6946d6298e3b8.jpeg', '2025-12-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('226', '2', 'Celebrating a Fantastic Term! Class 3 onwards', 'What a way to finish! Our senior students wrapped up the term with a high-energy celebration. It was wonderful to see them bonding and enjoying their well-deserved break.', '69650184e3a8e.jpeg', '2025-12-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('227', '2', 'Tribute to our Great Leader!', 'On this Quaid-e-Azam Day, we pay tribute to the great leader Quaid-e-Azam Muhammad Ali Jinnah, whose unwavering determination, wisdom, and vision led to the creation of Pakistan. His principles of Unity, Faith, and Discipline continue to guide us and inspire future generations. We remember his remarkable struggle and renew our commitment to uphold his values through honesty, hard work, and national pride.', '696502ab6d7bd.jpeg', '2025-12-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('228', '1', 'Congratulations to Our CATSO Competition 2025 Winners!', 'We are immensely proud to celebrate the outstanding achievements of our brilliant students in the CATSO Competition 2025. Your hard work, dedication, and passion for excellence have truly paid off! Heartiest congratulations to all the winners for showcasing exceptional talent and determination. You have made your teachers, parents, and school extremely proud. We also applaud all participants for their enthusiasm and effort—every step you take brings you closer to success!', '6965039dd1805.jpeg', '2026-01-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('229', '1', 'MY Assessments Result Day', 'Celebrating growth, effort, and beautiful beginnings!\r\nA journey of curiosity, confidence, and care.\r\nEarly Years Result Day — tomorrow \r\nBecause every little step truly matters.', '696504cc4d7ec.jpeg', '2026-01-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('230', '2', 'PROUD MOMENTS: Mid-Year Assessment Success!', 'Hard work pays off! Today we celebrated the incredible achievements of our students during the Mid-Year Result Day.  Come see the faces of our future leaders!', '696505bae5cd6.jpeg', '2026-01-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('231', '1', 'Reflect. Revise. Rise.', 'Paper Review Session Tomorrow!\r\nFor Classes 3 till Pre-9\r\n\r\nA focused time to reflect on performance,\r\nrevise key concepts, and strengthen understanding.\r\nGuiding students through constructive feedback\r\nto support confidence, clarity, and continuous improvement.', '696506fd8bf06.jpeg', '2026-01-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('232', '2', 'Beyond the Grades: Celebrating Progress!', 'Today was all about the journey! Our seniors (Class 3 onwards) spent the day reviewing their papers and celebrating how far they’ve come since the start of the year.', '69650f145b2a0.jpeg', '2026-01-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('233', '2', 'New Year and Second Term Welcome', 'The New Year marks a fresh beginning and the start of the second term at our school. Students return with renewed energy, enthusiasm, and readiness to learn.\r\nThis new term brings exciting opportunities for growth, creativity, and achievement.\r\nWe look forward to a productive and successful journey ahead together.', '696fb4d3bb7a1.jpeg', '2026-01-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('234', '2', 'Class 1 New Year Resolutions', 'Class 1 students shared their New Year resolutions with great enthusiasm and excitement. They talked about simple goals such as being kind, helping others, and developing good habits.\r\nThe activity encouraged self-awareness, responsibility, and positive thinking among young learners.\r\nIt was a meaningful way to welcome the New Year and inspire students to make thoughtful choices.', '696fb52501662.jpeg', '2026-01-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('235', '2', 'Hands-On Learning with Breadboards – Grade 4', 'Grade 4 students participated in practical lessons exploring the internal connectivity of a breadboard. They gained hands-on experience by identifying and using different pins on the breadboard.\r\nThe activity helped students understand basic electronic connections through real-life application.\r\nThis interactive session enhanced curiosity, problem-solving skills, and practical learning in science.', '696fb586d0a50.jpeg', '2026-01-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('236', '2', 'From fluffy clouds to bright sunshine', 'Our Playgroup class little weather reporters explored the sky, pointed with tiny fingers and proudly made their very own weather reports.\r\nLearning through fun, laughter, and curiosity every day.', '696fb5df2cfc9.jpeg', '2026-01-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('237', '2', 'Tiny Hands, Big Curiosity', 'Our Class 2 learners explored the world with excitement by spinning the globe and discovering new places.\r\nThe activity sparked curiosity and helped students learn about different countries and locations in a fun, interactive way.\r\nIt encouraged observation, questioning, and a love for learning about the world around them.', '696fb63db70a1.jpeg', '2026-01-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('238', '2', 'Weather Reporter Fun!', 'Our tiny weather reporter made the third day of the weather report and had so much fun exploring the sunny day while looking at the sun with binoculars. Learning about weather the happy, playful way!', '69764eb3ae1dc.jpeg', '2026-01-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('239', '2', 'Tiny hands, tasty plans!', 'Our Nursery learners enjoyed a fun sandwich-making activity, learning while creating their own yummy treats.', '69764fb854324.jpeg', '2026-01-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('240', '1', 'Celebrating creativity and patriotism!', 'Our young learners showcased their talent in the Pehchan Pakistan Contest and were awarded certificates for their amazing artwork.', '6976505bc165f.jpeg', '2026-01-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('241', '2', '&#039;The Extraordinary Gardener!', 'Today, our little gardeners brought the story of &#039;The Extraordinary Gardener&#039; to life with a fun role play activity! From planting seeds of imagination to nurturing teamwork, they enjoyed every moment of the story, learning about the power of kindness and growth. It was a day full of creativity, laughter, and beautiful lessons in gardening and friendship!', '697650e358a6c.jpeg', '2026-01-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('242', '2', 'Friday Takeaways: My Lunch box', 'Our little learners of Class 1 got creative by making their own Lunchbox craft. As part of this fun activity, students matched their lunch with their partners and enjoyed finding their lunch buddies. This hands-on experience encouraged creativity, observation, and social interaction—making learning joyful and meaningful. A perfect blend of art, teamwork, and fun to wrap up our Friday!', '697651524b0fe.jpeg', '2026-01-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('243', '2', 'Celebrating achievement!', 'Heartiest congratulations to Eshaal Zafar (Class 9) and Rayaan Ehtisham (Class 10) from AECHS Campus for their outstanding performance in NMTC \r\nOut of 7,000 students, they secured a place among the Top 100 students, making us immensely proud! \r\nWishing them continued success and a bright future ahead.', '697651da66633.jpeg', '2026-01-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('244', '2', 'FRACTAL MINDS: MATH CIRCLE  Session', 'Students enjoyed an engaging FRACTAL MINDS: MATH CIRCLE orientation where they explored key concepts of Mathematics and Physics through hands-on activities. The interactive session sparked curiosity, enhanced understanding, and made learning fun and meaningful. A great learning experience for all!', '6976523daedda.jpeg', '2026-01-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('245', '2', 'Celebrating Our Students’ Achievements!', 'We are thrilled to share that our talented students from SKANS School System, AECHS Campus participated in WAICY 2025 (World Artificial Intelligence Competition for Youth), competing with over 132,000 students from 103 countries in the Elementary School Category – AI-Generated Video Track.\r\n\r\nOur learners received their prizes and certificates, marking their creativity, dedication, and global-level skills. This achievement reflects the hard work of our students, the encouragement of their parents, and SKANS’ commitment to nurturing confident, future-ready learners.', '697652ede7547.jpeg', '2026-01-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('246', '2', 'Hygiene Day Celebration', 'Today our little learners joyfully celebrated Hygiene Day.\r\nThey learned the importance of clean hands, healthy habits, and self-care.\r\nHappy habits today for a healthier tomorrow.', '6978fda0077ca.jpeg', '2026-01-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('247', '2', 'Celebrating Clean Habits &amp; Healthy Hearts!', 'Hygiene Day was filled with learning, laughter, and meaningful experiences as our students practiced essential life skills through activities, role play, and performances', '6978fe01df28f.jpeg', '2026-01-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('248', '2', 'Coffee Morning with Mothers!', 'Today was truly a beautiful and heart-warming celebration as we spent special moments with our wonderful mothers over a cup of coffee and endless smiles.\r\nOur little learners and their moms joyfully took part in engaging activities filled with love, laughter, and meaningful learning. From exploring primary colours through hands-on fun to understanding concepts like empty and full, each activity created precious bonding moments.\r\nThe room was filled with smiles as mothers and children learned side by side, creating memories that will be treasured forever', '6978fee57e1b3.jpeg', '2026-01-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('249', '2', 'From Tiny Buds… to Big Brews!', 'Our KGS little gardeners and their families came together for a magical morning of green, growth, and giggles!\r\nBuds &amp; Brews. A Plant Celebration &amp; Green Thumb Gathering ????\r\nwas filled with colorful plants, joyful activities, and hands-on fun, as our little ones learned, explored, and celebrated the beauty of nature! \r\nIt was truly a blooming success, where tiny hands planted big dreams and hearts grew greener with every smile!', '697ba0cded72d.jpeg', '2026-01-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('250', '2', 'Creativity in action!', 'Pre-Ninth students demonstrated hands-on learning by designing a Vernier Caliper using paper. The model was neatly constructed, clearly labelled, and reflected students’ understanding, creativity, and practical application of scientific concepts.', '697ba127a591a.jpeg', '2026-01-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('251', '2', 'Class 7 in action!', 'Class 7 students were involved in a reflective memoir writing exercise, responding to guided prompts that encouraged introspection and creative expression. This was followed by a gallery walk, allowing learners to read, appreciate, and benefit from each other&#039;s work. A worthwhile literacy experience that fostered creativity, confidence, and peer learning', '697ba1c47487b.jpeg', '2026-01-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('252', '1', 'Exciting Competition Alert!', 'Calling all young writers from Class 3 to 7! \r\nShow off your creativity in our Essay &amp; Story Writing Competition. \r\nDon’t miss this chance to express your ideas through writing!', '697ba270265a3.jpeg', '2026-01-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('253', '1', 'Farewell 2026!', 'From laughter to lessons, from silly moments to big dreams, every memory with Class 10 is a treasure!\r\nHere’s to celebrating friendships, journeys, and the beautiful moments that made us who we are.', '697ba2eb9417a.jpeg', '2026-01-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('254', '2', 'The Refined Roast - Class 1', 'Coffee morning of class 1 was a beautiful blend of learning, bonding, and togetherness. Parents and students actively participated in discussions, activities, and reflections on healthy habits. The session highlighted the importance of healthy food, active lifestyles, and positive routines at home. Meaningful interactions strengthened the connection between school and families. It was truly heartwarming to see children learning alongside their parents. Together, we took small steps toward building healthier and happier futures.', '697f978092f9f.jpg', '2026-01-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('255', '2', 'Class 2 Coffee Morning', '“How I see this world with my two little eyes” \r\nThrough curious minds, bright smiles, and innocent perspectives, our Class 2 learners shared their beautiful view of the world.\r\nA heart-warming coffee morning filled with creativity, conversations, and cherished moments with parents. \r\n\r\nخوبصورت ننھی آنکھوں سے دنیا کو دیکھنے کا انداز—\r\nمحبت، معصومیت اور سیکھنے کی خوشبو کے ساتھ۔', '697f98ef5d968.jpg', '2026-01-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('256', '2', 'Class 10 Farewell', 'Chapters close, but stories live on. \r\nMoments captured, memories sealed in hearts.\r\nToday we honor the journey you walked together.\r\nTomorrow welcomes new dreams and destinations.\r\nFarewell, Class 10—fly high.', '697f99a6b650d.jpeg', '2026-01-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('257', '2', 'Farewell 2026', 'A memorable moment as our Class 10 students received well-deserved titles from our esteemed guest Ms. Sabeen Abid and Vice Principal Ms. Tehseen Saad, recognizing their hard work and individuality.', '697f9b7abb009.jpeg', '2026-01-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('258', '2', 'Creative Writing Competition', 'Pens in motion, minds on fire, and hearts full of ideas—our students showcased remarkable creativity and confidence during the Creative Writing Competition. The event provided a platform for young writers to express their thoughts, imagination, and perspectives through the power of words. Each entry reflected originality, critical thinking, and a strong command of language, making the competition both inspiring and impactful. The enthusiasm and dedication displayed by the participants truly highlighted the literary talent nurtured within our students.', '697f9c4451289.jpg', '2026-01-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('259', '2', 'Show and Tell session with mothers!', 'Our Play Group learners enjoyed a joyful Show and Tell session with their mothers by their side. Little ones confidently shared about their favourite season and proudly showed their beautiful handmade crafts. With moms’ encouragement and smiles, the activity became a lovely bonding experience, building confidence, communication skills, and happy memories together.', '69882f6eaaf00.jpeg', '2026-02-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('260', '2', 'HSRC Robotic Competition!', 'Our brilliant students Shahbaz Ul Hasan, Abdullah Abbasi, and Musa Butt showcased exceptional intelligence and skill at the HSRC Robotic Competition!\r\nTheir innovative thinking and teamwork truly made us proud.\r\nA huge round of applause for their outstanding performance! Keep reaching for the stars!', '69882fbccaf14.jpeg', '2026-02-02');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('261', '2', 'SKIFA Cup', 'Our students played the SKIFA Cup with great confidence, teamwork, and sportsmanship. \r\nTheir energy and discipline on the field made us truly proud. Well done, champions!', '698830360d1b8.jpeg', '2026-02-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('262', '2', 'Exploring transitional  Devices!', 'Our students of  Pre 9th explored transitional devices through engaging group and individual activities. They actively participated, practiced connecting ideas, and successfully understood the topic.', '698830916a581.jpeg', '2026-02-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('263', '2', 'Exploring the Microscopic Structure of the Intestine ????', 'Today, our students observed the microscopic structure of the mammalian intestine, identifying key features such as villi, epithelial lining, and blood capillaries. This hands-on activity helped them understand how the intestine is specially adapted for digestion and absorption of nutrients.\r\n\r\nThrough microscopic learning, students strengthened their observation skills and connected textbook knowledge with real biological structures, making learning more meaningful and engaging.', '698831913863a.jpeg', '2026-02-03');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('264', '2', 'Kashmir Day Celebration', 'Our Kashmir Day celebration was a heartfelt tribute to courage, patience, and hope. Through posters, performances, and powerful expressions, students conveyed a strong message of unity and solidarity.\r\n\r\nThe event reflected collective prayers for peace, justice, and a brighter future for Kashmir, reminding everyone of the importance of empathy, awareness, and standing together as one nation.', '698831fa84686.jpeg', '2026-02-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('265', '2', 'Kashmir Day', 'On Kashmir Day, we stand in solidarity with our Kashmiri brothers and sisters. We remember their sacrifices, honor their resilience, and raise our voices for justice, peace, and the right to live with dignity. May hope, freedom, and peace prevail in the land of Kashmir. \r\nOur prayers and hearts are always with Kashmir.', '6988324086fbc.jpeg', '2026-02-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('266', '1', 'OPEN DAY 2026 at SKANS', 'We warmly invite parents and families to our Open Day to experience learning in action at SKANS. Step into our classrooms, explore our thoughtfully designed Learning Centers, and witness how joyful, child-centered education comes to life. \r\nDiscover a wide range of Co-Curricular Activities that support creativity, confidence, teamwork, and overall development beyond academics. Our Open Day is a wonderful opportunity to connect with our educators, understand our teaching approach, and see how we nurture young learners. \r\nDate: 13th February\r\nWe look forward to welcoming you and sharing the SKANS learning experience with you.', '698833090fe67.jpeg', '2026-02-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('267', '2', 'Robotics Fun!', 'Students of Class 1 explored the magic of circuits by making LED lights work using batteries. A bright and hands-on learning experience!', '698cd0ec1320b.jpeg', '2026-02-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('268', '2', 'Diving into Division!', 'Our students had a blast learning to share equally through fun role-play, and afterward they enjoyed a hands-on experience that made the concept even clearer. Math has never been this exciting!', '698cd15da3700.jpeg', '2026-02-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('269', '2', 'Little Botanists in Action!', 'Today, our little learner proudly presented her plant craft, showing the different parts of a plant with confidence. Through this hands-on activity, children learned about roots, stem, leaves, and flower in a fun and engaging way. This activity helped develop fine motor skills, creativity, and early science awareness while boosting confidence as learners shared their work', '698cd32ce0e78.jpeg', '2026-02-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('270', '1', 'Admissions Open Session 2026-27', 'A strong foundation today for a successful tomorrow.\r\nDiscover quality education, care, and creativity at SKANS.', '698cd4f512cbe.jpeg', '2026-02-10');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('271', '1', 'Admissions Open', 'Empowering students through Taekwondo — building discipline, confidence, self-control, and strength alongside academic excellence at SKANS.', '698cd53ebc338.jpeg', '2026-02-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('272', '2', 'Assembly Presentation', 'Today, our shining stars of Class 1-B beautifully presented an assembly on Perseverance. \r\nThrough their confident words and adorable role play, they reminded us that success comes to those who never give up.\r\nSo proud of our little learners for spreading such a powerful message at such a young age!', '699416b623b1d.jpeg', '2026-02-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('273', '2', 'Mesmerizing Welcome Performance on Open Day', 'Our junior girls presented a mesmerizing welcome performance on Open Day, setting a joyful and vibrant tone for the event. Their graceful expressions, confident stage presence, and coordinated movements captivated the audience.\r\n\r\nThe performance reflected dedication, teamwork, and enthusiasm, leaving parents and guests truly impressed. It was a beautiful start to the day and a proud moment for our school community.', '699417a5b157c.jpeg', '2026-02-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('274', '2', 'Taekwondo Display by Our Boys', 'Our boys showcased an impressive Taekwondo display, demonstrating strength, discipline, and confidence. Their powerful moves, synchronized techniques, and focused performance captivated the audience.\r\nThe display highlighted not only physical fitness but also self-control, determination, and teamwork. It was a thrilling presentation that reflected dedication and hard work, making the event even more memorable.', '699418033496d.jpeg', '2026-02-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('275', '2', 'Our Tech Hub', 'The interactive learning stations presented by our students at the Tech Hub highlighted creativity, innovation, and hands-on learning at its best.', '69941863600e3.jpeg', '2026-02-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('276', '2', 'Role Play on the Value of Perseverance', 'Students presented a meaningful role play highlighting the value of perseverance and appreciation. They demonstrated the importance of staying determined and valuing the efforts of others.\r\nThe presentation delivered a powerful message about resilience, patience, and positive thinking. It was an inspiring performance that encouraged everyone to keep striving for success despite challenges.', '69941bb5045ce.jpeg', '2026-02-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('277', '2', 'Reading Session', 'Today, we conducted an engaging reading session using the ORT reader Go Away, Floppy from the Oxford Reading Tree series. The learners participated with great enthusiasm and confidently joined in repeating the phrase, “Go away, Floppy!” using appropriate expression and actions.\r\n\r\nThe session was highly interactive and enjoyable, fostering active participation and strengthening their early reading skills. It was truly encouraging to see our young learners developing confidence and nurturing a growing love for books.', '69941c793bd98.jpeg', '2026-02-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('278', '2', 'A Wonderful KG Assembly Presentation – “The Very Hungry Caterpillar”', 'Today, our KG Class presented a beautiful and highly engaging assembly on the famous story “The Very Hungry Caterpillar.” \r\n\r\nThe children confidently performed and shared an amazing learning experience by integrating different concepts in one theme, including:\r\n\r\n???? Days of the Week\r\n???? Counting &amp; Food Items\r\n???? Healthy vs. Unhealthy Eating Habits \r\n???? Life Cycle / Stages of a Butterfly\r\n???? Storytelling and Vocabulary Development\r\n???? Confidence Building &amp; Stage Presentation Skills \r\nThrough this wonderful performance, our little stars not only entertained everyone but also delivered meaningful learning in a fun and creative way.', '6997be4c9a822.jpeg', '2026-02-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('279', '2', 'آج اسکول میں ہرے رنگ کا دن بڑی خوشی اور جوش سے منایا گی', 'بچوں نے ہرے رنگ کے خوبصورت لباس پہنے  اور گھر سے ہرے رنگ کے کھلونے بھی ساتھ لائے ۔\r\n\r\nپلے گروپ کے ننھے طلبہ نے گرین کولاج اور کلرنگ کی سرگرمی میں حصہ لیا ، جبکہ بلیو اور ییلو رنگ کو مکس کر کے سبز رنگ بنایا ۔\r\n\r\nیہ سرگرمیاں بچوں کے لیے سیکھنے اور خوشی کا حسین امتزاج ثابت ہوئیں', '6997bec730bf4.jpeg', '2026-02-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('280', '2', 'Little Hands, Big Learning!', 'Today our Nursery learners explored the magical process of seed germination by sowing seeds in the soil all by themselves! They carefully filled the pots, placed the seeds, and covered them with soil, learning that plants begin their journey from tiny seeds with love, care, water, and sunlight. \r\nThis hands-on activity sparked curiosity and excitement as our young gardeners are now eagerly waiting and observing the changes that will happen in the coming days. They are learning patience, responsibility, and the wonder of nature as they watch their seeds grow into plants!\r\nStay tuned as we continue to observe, explore, and discover the miracles of growth together!', '699b5c3d80e6f.jpeg', '2026-02-17');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('281', '2', 'Class-based Celebration', 'Grade 1’s class-based celebration on Animals was full of excitement and learning. Students enthusiastically participated in different activities, explored fun facts, and strengthened their understanding of the animal world in an engaging way.', '699b5d0314b25.jpeg', '2026-02-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('282', '1', 'Ramadan Kareem', 'On behalf of SKANS School Management, we wish our students, parents, and staff a blessed and peaceful Ramadan. \r\nMay this holy month bring joy, health, and countless blessings to you and your loved ones.', '699b5dd567b7e.jpeg', '2026-02-19');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('283', '2', 'Land Transport - Class Celebration', 'Beep beep! ???? Our little explorers in Playgroup had a wheel-y great time diving into the world of Land Transport today! From navigating our &quot;mini-roads&quot; on tricycles to learning the magic of the traffic lights—Red means Stop, Green means Go! It was a day filled with zooming cars, sturdy trucks, and lots of &quot;vroom-vroom&quot; fun as we practiced road safety and coordination. Watching our tiny drivers follow the zebra crossing and identify their favorite vehicles was the highlight of our week!', '69a490f920f3a.jpeg', '2026-02-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('284', '2', 'A fascinating world of chemical and physical changes!', 'Our brilliant Class 7 students dove into the fascinating world of chemical and physical changes today! Through hands-on activities, they not only learned the concepts but also practiced teamwork and collaboration. \r\nIt was amazing to see them experiment, observe, and share ideas in groups, making science both fun and memorable!', '69a4916ec5fc6.jpeg', '2026-02-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('285', '1', 'Proud Moment for Our CATSO Winners!', 'We are delighted to celebrate the outstanding achievement of our brilliant students in the CATSO Competition. Their hard work, confidence, and dedication have truly paid off.\r\n\r\nCongratulations to our shining stars for bringing pride to our school! May you continue to achieve greater heights and make us proud every day.\r\nKeep striving, keep shining!', '69a491fd534db.jpeg', '2026-02-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('286', '2', 'Pre-Board Exams', 'With months of dedication, late-night revisions, practice papers, and consistent effort, they are now ready to showcase their hard work and determination. We are incredibly proud of their commitment and resilience. \r\nWishing all our students confidence, focus, and great success as they step forward to achieve excellence. You’ve got this!', '69a4929f59568.jpeg', '2026-02-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('287', '2', 'Proud Moment!', 'We are incredibly proud to share that our brilliant student Shahbaz Ul Hassan has secured a Silver Medal in the International NEO Science Olympiad 2025–2026 (Mathematics)!', '69a492dc9e79a.jpeg', '2026-02-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('288', '2', 'Assembly Presentation - Playgroup', 'Our Playgroup presented a wonderful assembly on animals with beautiful headgears and a lovely performance! \r\nThe little ones looked adorable and confidently shared their parts, making the assembly colorful and full of joy. So proud of their efforts and enthusiasm!', '69a49342b9e6e.jpeg', '2026-02-26');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('289', '2', 'International NEO Science Olympiad 2025–2026 (Mathematics)', ',\r\nWe are incredibly proud to share that our brilliant student Shahbaz Ul Hassan has secured a Silver Medal in the International NEO Science Olympiad 2025–2026 (Mathematics)! \r\nHeartiest congratulations to Muhammad Mustafa and Abdul Saboor as well for their outstanding performance and remarkable results. \r\nYour dedication, hard work, and passion for excellence truly make the entire SKANS School System family proud. May you continue to shine and achieve even greater milestones in the future!', '69a493cdd1e46.jpeg', '2026-02-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('290', '2', 'IKCC Success!', 'We are delighted to share that our talented students have achieved remarkable success in the IKCC – International Kids Coding Competition, securing four certificates and making us immensely proud! \r\n\r\nHeartiest congratulations to:\r\n???? Hamna Salman (Class 5B)\r\n???? Hassan Zafar (Class 5B)\r\n???? Maryam Zafar (Class 6)\r\n???? Ghulam E Mustafa (Class 5B)\r\n\r\nYour creativity, logical thinking, and dedication truly reflect the spirit of innovation and excellence at SKANS School System – AECHS Campus. \r\nKeep coding, keep creating, and keep shining bright!', '69a49432cc182.jpeg', '2026-02-25');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('291', '2', 'Namaz Day!', 'Namaz Day in the blessed month of Ramadan \r\nTeaching our little ones that Ramadan is not just about fasting, but strengthening our connection with Allah through Salah.', '69a4958562b21.jpeg', '2026-02-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('292', '2', 'Action Words in Action!', 'Our learners of 1A and 1B brought verbs to life with energy and big smiles.', '69a49610d7dd3.jpeg', '2026-02-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('293', '2', 'NEO Science Olympiad 2025–2026 (Mathematics)', 'We are incredibly proud to share that our brilliant student Shahbaz Ul Hassan has secured a Silver Medal in the International NEO Science Olympiad 2025–2026 (Mathematics)! \r\nHeartiest congratulations to Muhammad Mustafa and Abdul Saboor as well for their outstanding performance and remarkable results. \r\nYour dedication, hard work, and passion for excellence truly make the entire SKANS School System family proud. May you continue to shine and achieve even greater milestones in the future, InshaAllah!', '69a69ddcc14a5.jpeg', '2026-02-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('294', '2', 'NEO Science Olympiad 2025–2026 (Mathematics)', 'We are incredibly proud to share that our brilliant student Shahbaz Ul Hassan has secured a Silver Medal in the International NEO Science Olympiad 2025–2026 (Mathematics)! \r\nHeartiest congratulations to Muhammad Mustafa and Abdul Saboor as well for their outstanding performance and remarkable results. \r\nYour dedication, hard work, and passion for excellence truly make the entire SKANS School System family proud. May you continue to shine and achieve even greater milestones in the future, InshaAllah!', '69a69d8d32ca5.jpeg', '2026-02-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('295', '2', 'Happy Women’s Day', 'On this Women’s Day, SKANS proudly celebrates the strength, dedication, and leadership of the incredible women who inspire, nurture, and shape the future every day. Happy Women’s Day!\r\nEmpowered women. Empowered education.', '69ae1b7e78326.jpeg', '2026-03-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('296', '1', 'International Mathematics Day!', 'Get ready for our Math Poster Parade from Playgroup to Class 2 happening this Monday! \r\nOur little learners will showcase their creativity and love for numbers in a fun and colorful way.', '69ae1bcf19a81.jpeg', '2026-03-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('297', '1', 'Early Years General Knowledge Quiz!', 'Our little learners are all set to show their smarts in the Early Years General Knowledge Quiz happening this Monday!\r\nGet ready for fun, learning, and lots of excitement! Stay tuned to cheer on our young explorers!', '69ae1c50982e6.jpeg', '2026-03-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('298', '2', 'Volcano Eruption Experiment', 'To make the learning more exciting, a volcano eruption experiment was demonstrated for KG class. The children were thrilled to see the volcano erupt and watched the experiment with great curiosity and excitement. It was a fun and memorable hands-on learning experience for our young explorers!', '69ae1cd606a02.jpeg', '2026-03-05');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('299', '2', 'Class Celebration – ORT Reader “Red and Blues”', 'Our little learners had a wonderful class celebration based on the ORT reader “Red and Blues.” The children came dressed in beautiful red and blue outfits, adding excitement and color to the day. \r\nDuring the activity, learners confidently recognized and read sight words from the story such as “we,” “reds,” and “the.”  It was lovely to see their growing reading skills and enthusiasm for learning.\r\n\r\nThe celebration was filled with smiles, fun learning moments, and proud achievements. We are so proud of our young readers for their confidence and participation!', '69ae1d6879120.jpeg', '2026-03-11');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('300', '2', 'Learning never stops', 'At our school, education continues beyond the classroom. Our dedicated teachers are conducting online classes to ensure that learning remains uninterrupted for our students. Even during challenging times, our educators stay committed to guiding, supporting, and inspiring their students through digital platforms.\r\n\r\nBecause for us, every lesson matters and every learning moment counts.', '69c962af4622f.jpeg', '2026-03-24');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('301', '2', 'Jummah-tul-Wida Mubarik!', 'May this Jummah-tul-Wida bring you peace, joy, and blessings. May your prayers be answered, and may you have a blessed day.', '69c96457dedb3.jpeg', '2026-03-20');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('302', '2', 'Eid-ul-Fitr', 'Dear Parents, wishing you and your family a happy eid mubarik!', '69c966363a294.jpeg', '2026-03-21');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('303', '2', 'Pre-Board Examination Result Day', 'The Pre-Board Examination Result Day was successfully held 18th March 2026.  \r\nStudents carefully reviewed their papers and reflected on their mistakes with the valuable guidance of their teachers, helping them identify areas for further improvement. Roll Number Slips for the Final Board Examination were also distributed to the students.\r\nWe wish all our students the very best for their upcoming exams. May you achieve great success!', '69c967101e260.jpeg', '2026-03-18');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('304', '2', 'EYE Parent Teacher Meeting', 'The Parent-Teacher Meeting was conducted successfully, providing a valuable opportunity to discuss each child’s progress, strengths, and areas for improvement. It was a productive and meaningful interaction, strengthening the partnership between school and parents for the better growth of our young learners.', '69dc3eea4f7b8.jpeg', '2026-04-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('305', '2', 'Fun learning about Shadows', 'Our young learners had a fun and engaging science activity today!\r\nThey explored the concept of shadows and practiced shadow matching with wild and aquatic animals. Through this hands-on activity, they developed observation skills, curiosity, and a deeper understanding of how shadows are formed. It was wonderful to see their excitement and joy while learning!', '69dc3f672168e.jpeg', '2026-04-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('306', '2', 'Today was full of happy “H” vibes in our class!', 'Our little learners of play group explored the letter sound /h/ in the most fun way! \r\nFirst, they did color stamping on the letter h —tap tap tap… so many colorful H’s! \r\nThen came the cutest part… tiny handprints on H —turning the letter into a masterpiece!\r\n\r\nWe heard lots of “h-h-h” sounds—like hat, hen , and house —and giggles filled the room! \r\n\r\nSo proud of our little stars for learning while having so much fun!', '69dc40c122bac.jpeg', '2026-04-09');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('307', '2', 'A delightful and engaging story time full of excitement and learning!', 'Our little learners enthusiastically listened to The Gingerbread Man, showing great interest and joy throughout the session . Their happy faces and curious minds made the moment extra special .\r\n\r\nAfter the storytelling, we had a fun and meaningful discussion  where children explored comprehension skills by answering who, what, and when questions. They confidently shared their ideas, identified characters, and beautifully recalled story events.\r\n\r\nIt was wonderful to see them connect with the story in their own words, enhancing their listening, thinking, and speaking skills  in such a fun and interactive way.', '69dc41500149d.jpeg', '2026-04-08');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('308', '2', 'Celebrating Success!', 'We are proud to share that Sibgaht Ullah, one of our brightest stars, has been awarded a prestigious scholarship! \r\nSibgaht Ullah shared his journey at SKANS School, reflecting on the hard work, dedication, and guidance he received along the way!', '69dc41ad3daaf.jpeg', '2026-04-07');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('309', '2', 'میرا پیارا پاکستان', 'ننھے پھولوں کی خوبصورت پیشکش نے دل جیت لیے،\r\nلیے یادگار بن گئی۔ محبتِ وطن کے رنگوں میں رنگی یہ اسمبلی سب کے', '69dc41fa6b0be.jpeg', '2026-04-06');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('310', '2', 'تخلیقی صلاحیتوں کامظاہرہ', 'اس سرگرمی کے ذریعے طلبہ نے حضور اکرم ﷺ کی ابتدائی زندگی کے اہم واقعات کو منظم اور واضح انداز میں سمجھا۔ فلو چارٹ بنانے سے نہ صرف ان کی سیکھنے کی صلاحیت میں اضافہ ہوا بلکہ انہوں نے بھرپور دلچسپی اور تخلیقی صلاحیتوں کا مظاہرہ بھی کیا۔ \r\nیہ ایک مفید سیشن تھا جس نے طلبہ کے علم اور پیشکش کی مہارتوں کو مزید بہتر بنایا۔', '69e673da51248.jpeg', '2026-04-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('311', '2', 'Parent–Teacher Meeting', 'A successful Parent–Teacher Meeting was conducted for Class 3 onwards today.\r\n\r\nIt was a meaningful and productive session where parents and teachers came together to discuss students’ progress, celebrate achievements, and plan for further growth.\r\nA heartfelt thank you to all parents for their valuable time, support, and collaboration. Together, we continue to build a strong bridge between home and school for our learners’ bright future.', '69e6747277d1a.jpeg', '2026-04-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('312', '2', 'Class 1 Activity', 'Learners explored shadows by pouring flour over animal toys. As they lifted the toys, beautiful shadow shapes appeared in the flour, making the activity both fun and engaging.', '69e6750d70a5c.jpeg', '2026-04-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('313', '2', 'Hands-on fun', 'K.G. mathematicians explored prisms today! Hands-on fun with 3D shapes and big discoveries.', '69e675915e6e0.jpeg', '2026-04-16');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('314', '2', 'Math Projects!', 'Class 3 A and B truly impressed everyone with their wonderful Math projects! The students not only showcased creativity and understanding in their work but also spoke with great confidence while presenting their ideas.\r\nIt was a delight to see such enthusiasm, clarity, and pride in their learning. Keep shining, young mathematicians!', '69e675ee986e8.jpeg', '2026-04-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('315', '2', 'Playgroup in action!', 'Our Playgroup presented a beautiful assembly on the Months of the Year.\r\nLittle stars shined bright as they confidently spoke and made learning so joyful and memorable!', '69e67650d98d3.jpeg', '2026-04-15');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('316', '2', 'Exploring Push and Pull Forces!', 'Our little learners of KG class had a blast exploring the world of forces today! From a high-energy game of Tug-of-War to pulling along their favorite toys and trolleys, the children practiced their &quot;Push&quot; and &quot;Pull&quot; skills in the sunshine. \r\n​Watching them work together and use their strength is always a highlight. It’s amazing how much science we can learn through simple, active play!', '69e6778e51596.jpeg', '2026-04-14');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('317', '2', 'Professions Day celebrations!', 'Our little stars had so much fun exploring different professions and learning through play!', '69e6784a5e2d7.jpeg', '2026-04-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('318', '2', 'A tiny splash of magic by Class 1-A!', 'Class 1-A truly made the Water Cycle come alive with their beautiful assembly. Our little stars spoke so confidently, performed so gracefully, and filled the room with pure joy and pride', '69e6789f2dcc6.jpeg', '2026-04-13');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('319', '2', 'Cultural show', 'Class 4 brought Pakistan’s rich cultural diversity to life through a vibrant and colorful activity! Students showcased different cultures of Pakistan through traditional food, lively dances, and unique regional styles, all beautifully dressed in cultural attire.\r\nThe class was full of excitement, creativity, and pride as students celebrated unity in diversity. It was wonderful to see them learn about and appreciate the beauty of our country’s traditions in such an engaging way.', '69f9478d95e54.jpeg', '2026-05-04');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('320', '2', 'Shapes in Action!', '​Our Playgroup stars took center stage today for a brilliant assembly presentation all about shapes! From soaring triangles to rolling circles, our little learners showcased their knowledge with so much confidence and joy.', '69f949dd261ea.jpeg', '2026-04-28');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('321', '2', 'Little hearts, big lessons', 'Our Grade 2 stars delivered a heart-touching role play on humanity, reminding us that kindness begins small but shines bright.', '69f9487492983.jpeg', '2026-04-29');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('322', '2', 'Class 1 – Floating in Adjective Clouds', 'Our Class 1 learners had a joyful celebration while exploring the topic Adjectives. They began with a fun circle time, where students shared and practiced describing words with confidence.', '69fa2f148a9bb.jpeg', '2026-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('323', '2', 'KG Class-based Celebration', 'Shaping up some math fun! \r\nK.G. got hands-on with play-dough and sticks to craft their own 3D shapes.', '69fa2fc3c0aed.jpeg', '2026-04-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('324', '2', 'Green Expression Day – Class 3 Celebration', 'Our young eco-heroes of Class 3 are stepping forward to celebrate Green Expression Day, spreading awareness about the importance of planting trees and protecting our environment.', '69fa30d62d2cb.jpeg', '2026-04-30');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('325', '2', 'Assembly Presentation: “I Am a Citizen”', 'Our bright little stars of Class 1A proudly presented their assembly on “I Am a Citizen” \r\nThey beautifully highlighted values of kindness, responsibility, and respect. \r\nA heartwarming reminder that even the smallest steps can shape responsible citizens of tomorrow.', '69fa3150c635d.jpeg', '2026-04-27');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('326', '2', 'Fun with Loud &amp; Soft Sounds!', 'Our little learners had an exciting activity time exploring loud and soft  sounds using different objects and instruments!\r\n\r\nFrom gently shaking to making big sounds, the children discovered how sounds can be quiet like a whisper or loud like a drum beat. They were curious, engaged, and full of joy while experimenting and learning! \r\n\r\nThis hands-on activity helped them build listening skills, understand sound differences, and express themselves creatively', '69fa31f7c9343.jpeg', '2026-04-23');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('327', '2', 'Exploring Patterns with Tie &amp; Dye Fun!', 'Our little learners had a joyful and creative day as they explored the world of colors and patterns through a fun Tie &amp; Dye activity! From swirling designs to crinkled textures, children discovered how simple folds can turn into beautiful patterns.', '69fa325746bde.jpeg', '2026-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('328', '2', 'Playgroup Earth Day Collage Activity', 'Our tiniest eco-explorers of Playgroup had a wonderful time today creating their Earth Day collage.\r\nWith little hands full of excitement, they carefully pasted fresh leaves on Earth cutouts, turning simple pieces into beautiful green masterpieces .', '69fa32b65cb0a.jpeg', '2026-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('329', '2', 'Earth Day Celebration', 'Our Nursery little stars celebrated Earth Day in the most creative and joyful way.\r\nWith their tiny hands dipped in colors, they made beautiful handprints showing their love for our planet.\r\nIt was such a delightful moment to see their excitement, laughter, and curiosity while creating something so meaningful. Each little print reflected their innocence and growing love for Mother Earth .', '69fa330f01337.jpeg', '2026-04-22');
INSERT INTO news_events (`id`, `category_id`, `title`, `description`, `image_url`, `date`) VALUES ('330', '2', 'PE Fun Time!', 'Energy, laughter, and endless smiles filled the air as our little champs enjoyed their PE session. From running and jumping to playful activities, every moment was full of excitement and active learning. Keeping our bodies strong and our hearts happy.', '69fa33904a241.jpeg', '2026-04-21');
